    ('03', 'Kehidupan Sehat dan Sejahtera', '3.2', 'Pada tahun 2030, mengakhiri kematian bayi baru lahir dan balita yang dapat dicegah, dengan seluruh negara berusaha menurunkan Angka Kematian Neonatal setidaknya hingga 12 per 1000 KH (Kelahiran Hidup) dan Angka Kematian Balita 25 per 1000.', '3.2.1*', '(a) Angka Kematian Balita (AKBa); (b) Angka Kematian Bayi (AKB) per 1.000 kelahiran hidup.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.2', 'Pada tahun 2030, mengakhiri kematian bayi baru lahir dan balita yang dapat dicegah, dengan seluruh negara berusaha menurunkan Angka Kematian Neonatal setidaknya hingga 12 per 1000 KH (Kelahiran Hidup) dan Angka Kematian Balita 25 per 1000.', '3.2.2*', 'Angka Kematian Neonatal (AKN) per 1.000 kelahiran hidup.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.3', 'Pada tahun 2030, mengakhiri epidemi AIDS, tuberkulosis, malaria, dan penyakit tropis yang terabaikan, dan memerangi hepatitis, penyakit bersumber air, serta penyakit menular lainnya.', '3.3.1*', 'Jumlah infeksi baru HIV per 1000 penduduk tidak terinfeksi.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.3', 'Pada tahun 2030, mengakhiri epidemi AIDS, tuberkulosis, malaria, dan penyakit tropis yang terabaikan, dan memerangi hepatitis, penyakit bersumber air, serta penyakit menular lainnya.', '3.3.2*', 'Insidens Tuberkulosis (ITB) per 100.000 penduduk.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.3', 'Pada tahun 2030, mengakhiri epidemi AIDS, tuberkulosis, malaria, dan penyakit tropis yang terabaikan, dan memerangi hepatitis, penyakit bersumber air, serta penyakit menular lainnya.', '3.3.3*', 'Kejadian Malaria per 1.000 orang.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.3', 'Pada tahun 2030, mengakhiri epidemi AIDS, tuberkulosis, malaria, dan penyakit tropis yang terabaikan, dan memerangi hepatitis, penyakit bersumber air, serta penyakit menular lainnya.', '3.3.3.(a)', 'Jumlah kabupaten/kota yang mencapai eliminasi malaria.', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.3', 'Pada tahun 2030, mengakhiri epidemi AIDS, tuberkulosis, malaria, dan penyakit tropis yang terabaikan, dan memerangi hepatitis, penyakit bersumber air, serta penyakit menular lainnya.', '3.3.4*', 'Insiden Hepatitis B per 100.000 penduduk.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.3', 'Pada tahun 2030, mengakhiri epidemi AIDS, tuberkulosis, malaria, dan penyakit tropis yang terabaikan, dan memerangi hepatitis, penyakit bersumber air, serta penyakit menular lainnya.', '3.3.5*', 'Jumlah orang yang memerlukan intervensi terhadap penyakit tropis yang terabaikan (a) Filariasis dan (b) Kusta.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.3', 'Pada tahun 2030, mengakhiri epidemi AIDS, tuberkulosis, malaria, dan penyakit tropis yang terabaikan, dan memerangi hepatitis, penyakit bersumber air, serta penyakit menular lainnya.', '3.3.5.(a)', 'Jumlah kabupaten/kota dengan eliminasi kusta.', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.3', 'Pada tahun 2030, mengakhiri epidemi AIDS, tuberkulosis, malaria, dan penyakit tropis yang terabaikan, dan memerangi hepatitis, penyakit bersumber air, serta penyakit menular lainnya.', '3.3.5.(b)', 'Jumlah kabupaten/kota endemis filariasis yang mencapai eliminasi.', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.4', 'Pada tahun 2030, mengurangi hingga sepertiga angka kematian dini akibat penyakit tidak menular, melalui pencegahan dan pengobatan, serta meningkatkan kesehatan mental dan kesejahteraan.', '3.4.1', 'Kematian akibat penyakit kardiovaskuler, kanker, diabetes atau penyakit pernapasan kronis.', 'Tanpa klasifikasi', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.4', 'Pada tahun 2030, mengurangi hingga sepertiga angka kematian dini akibat penyakit tidak menular, melalui pencegahan dan pengobatan, serta meningkatkan kesehatan mental dan kesejahteraan.', '3.4.1.(a)', 'Persentase merokok penduduk usia 10-18 tahun.', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.4', 'Pada tahun 2030, mengurangi hingga sepertiga angka kematian dini akibat penyakit tidak menular, melalui pencegahan dan pengobatan, serta meningkatkan kesehatan mental dan kesejahteraan.', '3.4.1.(b)', 'Prevalensi tekanan darah tinggi.', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.4', 'Pada tahun 2030, mengurangi hingga sepertiga angka kematian dini akibat penyakit tidak menular, melalui pencegahan dan pengobatan, serta meningkatkan kesehatan mental dan kesejahteraan.', '3.4.1.(c)', 'Prevalensi obesitas pada penduduk umur ≥18 tahun.', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.4', 'Pada tahun 2030, mengurangi hingga sepertiga angka kematian dini akibat penyakit tidak menular, melalui pencegahan dan pengobatan, serta meningkatkan kesehatan mental dan kesejahteraan.', '3.4.2*', 'Kematian akibat bunuh diri (incidence rate).', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.5', 'Memperkuat pencegahan dan pengobatan penyalahgunaan zat, termasuk penyalahgunaan narkotika dan penggunaan alkohol yang membahayakan.', '3.5.1*', 'Cakupan intervensi pengobatan (farmakologi, psikososial, rehabilitasi dan layanan pasca intervensi) bagi gangguan penyalahgunaan zat.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.5', 'Memperkuat pencegahan dan pengobatan penyalahgunaan zat, termasuk penyalahgunaan narkotika dan penggunaan alkohol yang membahayakan.', '3.5.1.(a)', 'Jumlah penyalahguna napza yang mendapatkan pelayanan rehabilitasi medis', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.5', 'Memperkuat pencegahan dan pengobatan penyalahgunaan zat, termasuk penyalahgunaan narkotika dan penggunaan alkohol yang membahayakan.', '3.5.2', 'Konsumsi alkohol (liter per kapita) oleh penduduk umur ≥15 tahun dalam satu tahun terakhir.', 'Tanpa klasifikasi', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.6', 'Pada tahun 2020, mengurangi hingga setengah jumlah kematian global dan cedera dari kecelakaan lalu lintas.', '3.6.1', 'Kematian akibat kecelakaan lalu lintas.', 'Tanpa klasifikasi', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.7', 'Pada tahun 2030, menjamin akses universal terhadap layanan kesehatan seksual dan reproduksi, termasuk keluarga berencana, informasi dan pendidikan, dan integrasi kesehatan reproduksi ke dalam strategi dan program nasional.', '3.7.1*', 'Proporsi perempuan usia reproduksi (15-49 tahun) yang memiliki kebutuhan keluarga berencana terpenuhi menurut metode kontrasepsi modern.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.7', 'Pada tahun 2030, menjamin akses universal terhadap layanan kesehatan seksual dan reproduksi, termasuk keluarga berencana, informasi dan pendidikan, dan integrasi kesehatan reproduksi ke dalam strategi dan program nasional.', '3.7.2*', 'Angka kelahiran remaja (umur 10-14 tahun; umur 15-19 tahun) per 1000 perempuan di kelompok umur yang sama.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.7', 'Pada tahun 2030, menjamin akses universal terhadap layanan kesehatan seksual dan reproduksi, termasuk keluarga berencana, informasi dan pendidikan, dan integrasi kesehatan reproduksi ke dalam strategi dan program nasional.', '3.7.2.(a)', 'Total Fertility Rate (TFR).', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.8', 'Mencapai cakupan kesehatan universal, termasuk perlindungan risiko keuangan, akses terhadap pelayanan kesehatan dasar yang baik, dan akses terhadap obat- obatan dan vaksin dasar yang aman, efektif, berkualitas, dan terjangkau bagi semua orang.', '3.8.1*', 'Cakupan pelayanan kesehatan essensial.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.8', 'Mencapai cakupan kesehatan universal, termasuk perlindungan risiko keuangan, akses terhadap pelayanan kesehatan dasar yang baik, dan akses terhadap obat- obatan dan vaksin dasar yang aman, efektif, berkualitas, dan terjangkau bagi semua orang.', '3.8.1.(a)', 'Unmet Need Pelayanan Kesehatan.', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.8', 'Mencapai cakupan kesehatan universal, termasuk perlindungan risiko keuangan, akses terhadap pelayanan kesehatan dasar yang baik, dan akses terhadap obat- obatan dan vaksin dasar yang aman, efektif, berkualitas, dan terjangkau bagi semua orang.', '3.8.2*', 'Proporsi populasi dengan pengeluaran rumah tangga yang besar untuk kesehatan sebagai bagian dari total pengeluaran rumah tangga atau pendapatan.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.8', 'Mencapai cakupan kesehatan universal, termasuk perlindungan risiko keuangan, akses terhadap pelayanan kesehatan dasar yang baik, dan akses terhadap obat- obatan dan vaksin dasar yang aman, efektif, berkualitas, dan terjangkau bagi semua orang.', '3.8.2.(a)', 'Cakupan Kepesertaan Jaminan Kesehatan Nasional (JKN).', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.9', 'Pada tahun 2030, secara signifikan mengurangi jumlah kematian dan kesakitan akibat bahan kimia berbahaya, serta polusi dan kontaminasi udara, air, dan tanah.', '3.9.1.(a)', 'Angka kematian akibat polusi rumah tangga dan udara ambien (luar ruangan).', 'Proxy', 'APPLICABLE', 'Apakah project menerapkan praktik yang mengurangi risiko polusi udara dari kegiatan (misalnya menghindari pembakaran lahan dan emisi bahan bakar yang berbahaya)?', 'Menilai kontribusi project dalam mengurangi polusi udara yang berasal dari kegiatan pertanian.'),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.9', 'Pada tahun 2030, secara signifikan mengurangi jumlah kematian dan kesakitan akibat bahan kimia berbahaya, serta polusi dan kontaminasi udara, air, dan tanah.', '3.9.2.(a)', 'Angka kematian akibat air yang tidak aman, sanitasi yang tidak aman dan kurangnya kebersihan (Water, Sanitation and Hygiene for All (WASH) services)', 'Proxy', 'APPLICABLE', 'Apakah project menyediakan akses air bersih, sanitasi, dan fasilitas kebersihan bagi pekerja, petani, atau penerima manfaat yang terlibat?', 'Menilai kontribusi project terhadap ketersediaan air bersih dan sanitasi bagi pihak yang terlibat.'),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.9', 'Pada tahun 2030, secara signifikan mengurangi jumlah kematian dan kesakitan akibat bahan kimia berbahaya, serta polusi dan kontaminasi udara, air, dan tanah.', '3.9.3.(a)', 'Angka kematian akibat keracunan yang tidak disengaja.', 'Proxy', 'APPLICABLE', 'Apakah project menerapkan pengelolaan bahan kimia (seperti pestisida, pupuk) yang aman untuk mencegah risiko keracunan bagi pekerja dan petani?', 'Menilai pengelolaan bahan kimia secara aman untuk mencegah keracunan pada pihak yang terlibat.'),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.a', 'Memperkuat pelaksanaan the Framework Convention on Tobacco Control WHO di seluruh negara sebagai langkah yang tepat.', '3.a.1*', 'Persentase merokok pada penduduk umur ≥15 tahun.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.b', 'Mendukung penelitian dan pengembangan vaksin dan obat penyakit menular dan tidak menular yang terutama berpengaruh terhadap negara berkembang, menyediakan akses terhadap obat dan vaksin dasar yang terjangkau, sesuai the Doha Declaration tentang the TRIPS Agreement and Public Health, yang menegaskan hak negara berkembang untuk menggunakan secara penuh ketentuan dalam Kesepakatan atas Aspek-Aspek Perdagangan dari Hak Kekayaan Intelektual terkait keleluasaan untuk melindungi kesehatan masyarakat, dan khususnya, menyediakan akses obat bagi semua.', '3.b.1*', 'Proporsi target populasi yang telah memperoleh vaksin program nasional.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.b', 'Mendukung penelitian dan pengembangan vaksin dan obat penyakit menular dan tidak menular yang terutama berpengaruh terhadap negara berkembang, menyediakan akses terhadap obat dan vaksin dasar yang terjangkau, sesuai the Doha Declaration tentang the TRIPS Agreement and Public Health, yang menegaskan hak negara berkembang untuk menggunakan secara penuh ketentuan dalam Kesepakatan atas Aspek-Aspek Perdagangan dari Hak Kekayaan Intelektual terkait keleluasaan untuk melindungi kesehatan masyarakat, dan khususnya, menyediakan akses obat bagi semua.', '3.b.2*', 'Total official development assistance (ODA) untuk penelitian medis dan sektor kesehatan dasar.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.b', 'Mendukung penelitian dan pengembangan vaksin dan obat penyakit menular dan tidak menular yang terutama berpengaruh terhadap negara berkembang, menyediakan akses terhadap obat dan vaksin dasar yang terjangkau, sesuai the Doha Declaration tentang the TRIPS Agreement and Public Health, yang menegaskan hak negara berkembang untuk menggunakan secara penuh ketentuan dalam Kesepakatan atas Aspek-Aspek Perdagangan dari Hak Kekayaan Intelektual terkait keleluasaan untuk melindungi kesehatan masyarakat, dan khususnya, menyediakan akses obat bagi semua.', '3.b.3*', 'Proporsi fasilitas kesehatan dengan paket obat essensial yang tersedia dan terjangkau secara berkelanjutan.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.c', 'Meningkatkan secara signifikan pembiayaan kesehatan dan rekrutmen, pengembangan, pelatihan, dan retensi tenaga kesehatan di negara berkembang, khususnya negara kurang berkembang, dan negara berkembang pulau kecil.', '3.c.1*', 'Kepadatan dan distribusi tenaga kesehatan.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('03', 'Kehidupan Sehat dan Sejahtera', '3.d', 'Memperkuat kapasitas semua negara, khususnya negara berkembang tentang peringatan dini, pengurangan risiko dan manajemen risiko kesehatan nasional dan global.', '3.d.1*', 'Regulasi kesehatan internasional dan kesiapsiagaan darurat kesehatan.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('04', 'Pendidikan Berkualitas', '4.1', 'Pada tahun 2030, menjamin bahwa semua anak perempuan dan laki-laki menyelesaikan pendidikan dasar dan menengah tanpa dipungut biaya, setara, dan berkualitas, yang mengarah pada capaian pembelajaran yang relevan dan efektif.', '4.1.1.(a)', 'Proporsi anak-anak dan remaja di: (a) kelas 5, (b) kelas 8, dan (c) kelas 11 yang mencapai setidaknya tingkat kemahiran minimum dalam: (i) literasi membaca, (ii) numerasi.', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('04', 'Pendidikan Berkualitas', '4.1', 'Pada tahun 2030, menjamin bahwa semua anak perempuan dan laki-laki menyelesaikan pendidikan dasar dan menengah tanpa dipungut biaya, setara, dan berkualitas, yang mengarah pada capaian pembelajaran yang relevan dan efektif.', '4.1.2*', 'Tingkat penyelesaian pendidikan jenjang SD/sederajat, SMP/sederajat, dan SMA/sederajat.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('04', 'Pendidikan Berkualitas', '4.1', 'Pada tahun 2030, menjamin bahwa semua anak perempuan dan laki-laki menyelesaikan pendidikan dasar dan menengah tanpa dipungut biaya, setara, dan berkualitas, yang mengarah pada capaian pembelajaran yang relevan dan efektif.', '4.1.2.(a)', 'Angka anak tidak sekolah usia 7-12 tahun; usia 13-15 tahun; dan usia 16-18 tahun.', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('04', 'Pendidikan Berkualitas', '4.2', 'Pada tahun 2030, menjamin bahwa semua anak perempuan dan laki-laki memiliki akses terhadap perkembangan dan pengasuhan anak usia dini, pengasuhan, pendidikan pra-sekolah dasar yang berkualitas, sehingga mereka siap untuk menempuh pendidikan dasar.', '4.2.1*', 'Proporsi anak usia 24-59 bulan yang berkembang dengan baik dalam bidang kesehatan, pembelajaran, dan psikososial, menurut jenis kelamin.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('04', 'Pendidikan Berkualitas', '4.2', 'Pada tahun 2030, menjamin bahwa semua anak perempuan dan laki-laki memiliki akses terhadap perkembangan dan pengasuhan anak usia dini, pengasuhan, pendidikan pra-sekolah dasar yang berkualitas, sehingga mereka siap untuk menempuh pendidikan dasar.', '4.2.2*', 'Tingkat partisipasi dalam pembelajaran yang teroganisir (satu tahun sebelum usia sekolah dasar), menurut jenis kelamin.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('04', 'Pendidikan Berkualitas', '4.3', 'Pada tahun 2030, menjamin akses yang sama bagi semua perempuan dan laki-laki, terhadap pendidikan teknik, kejuruan dan pendidikan tinggi, termasuk universitas, yang terjangkau dan berkualitas.', '4.3.1*', 'Tingkat partisipasi remaja dan dewasa dalam pendidikan dan pelatihan formal dan nonformal dalam 12 bulan terakhir, menurut jenis kelamin.', 'Nasional/Global', 'APPLICABLE', 'Apakah project menyediakan atau memfasilitasi pelatihan dan pendidikan nonformal (misalnya pelatihan budidaya, pengolahan, manajemen usaha) bagi petani, pekerja, atau penerima manfaat tanpa membedakan jenis kelamin?', 'Menilai kontribusi project terhadap akses pelatihan/keterampilan bagi peserta project.'),
    ('04', 'Pendidikan Berkualitas', '4.3', 'Pada tahun 2030, menjamin akses yang sama bagi semua perempuan dan laki-laki, terhadap pendidikan teknik, kejuruan dan pendidikan tinggi, termasuk universitas, yang terjangkau dan berkualitas.', '4.3.1.(a)', 'Angka Partisipasi Kasar (APK) Perguruan Tinggi (PT).', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('04', 'Pendidikan Berkualitas', '4.4', 'Pada tahun 2030, meningkatkan secara signifikan jumlah pemuda dan orang dewasa yang memiliki keterampilan yang relevan, termasuk keterampilan teknik dan kejuruan, untuk pekerjaan, pekerjaan yang layak dan kewirausahaan.', '4.4.1.(a)', 'Proporsi remaja (usia 15-24 tahun) dan dewasa (usia 15-59 tahun) dengan keterampilan teknologi informasi dan komunikasi (TIK).', 'Proxy', 'APPLICABLE', 'Apakah project meningkatkan keterampilan TIK petani, pekerja, atau penerima manfaat (misalnya penggunaan aplikasi pertanian, telepon pintar, dan alat digital) untuk mendukung kegiatan mereka?', 'Menilai kontribusi project terhadap peningkatan keterampilan digital peserta.'),
    ('04', 'Pendidikan Berkualitas', '4.5', 'Pada tahun 2030, menghilangkan disparitas gender dalam pendidikan, dan menjamin akses yang sama untuk semua tingkat pendidikan dan pelatihan kejuruan, bagi masyarakat rentan termasuk penyandang cacat, masyarakat penduduk asli, dan anak-anak dalam kondisi rentan.', '4.5.1*', 'Rasio Angka Partisipasi Murni (APM) pada tingkat SD/sederajat, dan (ii) Rasio Angka Partisipasi Kasar (APK) pada tingkat SMP/sederajat, SMA/SMK/sederajat, dan Perguruan Tinggi untuk (a) perempua/laki-laki, (b) Perdesaan/perkotaan, (c) kuintil terbawah/teratas, (d) disabilitas/tanpa disabilitas.', 'Nasional/Global', 'APPLICABLE', 'Apakah project memberikan akses pelatihan dan pengembangan kapasitas secara setara, termasuk bagi perempuan dan kelompok rentan yang terlibat?', 'Menilai kesetaraan akses pelatihan dalam project.'),
    ('04', 'Pendidikan Berkualitas', '4.6', 'Pada tahun 2030, menjamin bahwa semua remaja dan proporsi kelompok dewasa tertentu, baik laki-laki maupun perempuan, memiliki kemampuan literasi dan numerasi.', '4.6.1.(a)', 'Persentase angka melek aksara penduduk umur ≥15 tahun.', 'Proxy', 'APPLICABLE', 'Apakah project memiliki kegiatan penguatan kapasitas dasar (literasi dan numerasi) bagi petani atau penerima manfaat yang mendukung pengelolaan usaha tani?', 'Menilai kontribusi project terhadap kemampuan dasar literasi/numerasi peserta untuk mendukung kegiatan.'),
    ('04', 'Pendidikan Berkualitas', '4.a', 'Membangun dan meningkatkan fasilitas pendidikan yang ramah anak, ramah penyandang cacat dan gender, serta menyediakan lingkungan belajar yang aman, anti kekerasan, inklusif dan efektif bagi semua.', '4.a.1*', 'Proporsi sekolah dengan akses terhadap: (a) listrik (b) internet untuk tujuan pengajaran, (c) komputer untuk tujuan pengajaran, (d) air minum layak, (e) fasilitas sanitasi dasar per jenis kelamin, (f) fasilitas cuci tangan (terdiri air, sanitasi, dan higienis bagi semua (WASH).', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('04', 'Pendidikan Berkualitas', '4.a', 'Membangun dan meningkatkan fasilitas pendidikan yang ramah anak, ramah penyandang cacat dan gender, serta menyediakan lingkungan belajar yang aman, anti kekerasan, inklusif dan efektif bagi semua.', '4.a.1.(a)', 'Persentase siswa yang mengalami perundungan dalam 12 bulan terakhir.', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('04', 'Pendidikan Berkualitas', '4.7', 'Pada tahun 2030, menjamin semua peserta didik memperoleh pengetahuan dan keterampilan yang diperlukan untuk meningkatkan pembangunan berkelanjutan, termasuk antara lain, melalui pendidikan untuk pembangunan berkelanjutan dan gaya hidup yang berkelanjutan, hak asasi manusia, kesetaraan gender, promosi budaya damai dan non kekerasan, kewarganegaraan global dan penghargaan terhadap keanekaragaman budaya dan kontribusi budaya terhadap pembangunan berkelanjutan.', '4.7.1', 'Pengarusutamaan (i) pendidikan kewargaan global, dan (ii) pendidikan pembangunan berkelanjutan termasuk kesetaraan gender dan hak asasi manusia yang tercantum dalam (a) kebijakan pendidikan, (b) kurikulum pendidikan, (c) pelatihan guru, (d) asesmen siswa, pada jenjang pendidikan dasar dan menengah.', 'Tanpa klasifikasi', 'APPLICABLE', 'Apakah project menyelenggarakan pendidikan atau pelatihan mengenai praktik pertanian berkelanjutan dan pembangunan berkelanjutan bagi petani dan penerima manfaat?', 'Menilai kontribusi project dalam edukasi pembangunan berkelanjutan bagi peserta.'),
    ('04', 'Pendidikan Berkualitas', '4.b', 'Pada tahun 2020, secara signifikan memperluas secara global, jumlah beasiswa bagi negara berkembang, khususnya negara kurang berkembang, negara berkembang pulau kecil, dan negara-negara Afrika, untuk mendaftar di pendidikan tinggi, termasuk pelatihan kejuruan, teknologi informasi dan komunikasi, program teknik, program rekayasa dan ilmiah, di negara maju dan negara berkembang lainnya.', '4.b.1*', 'Jumlah bantuan resmi Pemerintah Indonesia kepada mahasiswa asing penerima beasiswa kemitraan negara berkembang.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('04', 'Pendidikan Berkualitas', '4.c', 'Pada tahun 2030, secara signifikan meningkatkan pasokan guru yang berkualitas, termasuk melalui kerjasama internasional dalam pelatihan guru di negara berkembang, terutama negara kurang berkembang, dan negara berkembang kepulauan kecil.', '4.c.1*', 'Persentase guru yang memenuhi kualifikasi sesuai dengan standar nasional menurut jenjang pendidikan.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('05', 'Kesetaraan Gender', '5.1', 'Mengakhiri segala bentuk diskriminasi terhadap kaum perempuan dimanapun.', '5.1.1*', 'Ketersediaan kerangka hukum yang mendorong, menetapkan dan memantau kesetaraan gender dan penghapusan diskriminasi berdasarkan jenis kelamin.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('05', 'Kesetaraan Gender', '5.2', 'Menghapuskan segala bentuk kekerasan terhadap kaum perempuan di ruang publik dan pribadi, termasuk perdagangan orang dan eksploitasi seksual, serta berbagai jenis eksploitasi lainnya.', '5.2.1*', 'Proporsi perempuan dewasa dan anak perempuan (umur 15-64 tahun mengalami kekerasan (fisik, seksual, atau emosional) oleh pasangan atau mantan pasangan dalam 12 bulan terakhir.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('05', 'Kesetaraan Gender', '5.2', 'Menghapuskan segala bentuk kekerasan terhadap kaum perempuan di ruang publik dan pribadi, termasuk perdagangan orang dan eksploitasi seksual, serta berbagai jenis eksploitasi lainnya.', '5.2.2*', 'Proporsi perempuan dewasa dan anak perempuan (umur 15-64 tahun) mengalami kekerasan seksual oleh orang lain selain pasangan dalam 12 bulan terakhir.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('05', 'Kesetaraan Gender', '5.3', 'Menghapuskan semua praktik berbahaya, seperti perkawinan usia anak, perkawinan dini dan paksa, serta sunat perempuan.', '5.3.1*', 'Proporsi perempuan umur 20 - 24 tahun yang usia kawin pertama atau usia hidup bersama pertama (a) sebelum umur 15 tahun dan (b) sebelum umur 18 tahun.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('05', 'Kesetaraan Gender', '5.3', 'Menghapuskan semua praktik berbahaya, seperti perkawinan usia anak, perkawinan dini dan paksa, serta sunat perempuan.', '5.3.2.(a)', 'Proporsi anak perempuan dari perempuan umur 15-49 tahun yang tinggal bersama dan menjalankan praktik sunat perempuan.', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('05', 'Kesetaraan Gender', '5.5', 'Menjamin partisipasi penuh dan efektif, dan kesempatan yang sama bagi perempuan untuk memimpin di semua tingkat pengambilan keputusan dalam kehidupan politik, ekonomi, dan masyarakat.', '5.5.1*', 'Proporsi kursi yang diduduki perempuan di (a) parlemen tingkat pusat dan (b pemerintah daerah.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('05', 'Kesetaraan Gender', '5.5', 'Menjamin partisipasi penuh dan efektif, dan kesempatan yang sama bagi perempuan untuk memimpin di semua tingkat pengambilan keputusan dalam kehidupan politik, ekonomi, dan masyarakat.', '5.5.2*', 'Proporsi perempuan yang berada di posisi managerial', 'Nasional/Global', 'APPLICABLE', 'Apakah project memberikan kesempatan yang setara bagi perempuan untuk menduduki posisi pengelolaan atau pengambilan keputusan dalam struktur project?', 'Menilai kesetaraan kesempatan kepemimpinan perempuan dalam project.'),
    ('05', 'Kesetaraan Gender', '5.6', 'Menjamin akses universal terhadap kesehatan seksual dan reproduksi, dan hak reproduksi seperti yang telah disepakati sesuai dengan Programme of Action of the International Conference on Population andDevelopment and the Beijing Platform serta dokumen-dokumen hasil reviu dari konferensi-konferensi tersebut.', '5.6.1*', 'Proporsi perempuan usia reproduksi 15-49 tahun yang membuat keputusan sendiri terkait hubungan seksual, penggunaan kontrasepsi, dan layanan kesehatan.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('05', 'Kesetaraan Gender', '5.6', 'Menjamin akses universal terhadap kesehatan seksual dan reproduksi, dan hak reproduksi seperti yang telah disepakati sesuai dengan Programme of Action of the International Conference on Population andDevelopment and the Beijing Platform serta dokumen-dokumen hasil reviu dari konferensi-konferensi tersebut.', '5.6.2*', 'Regulasi yang menjamin akses yang setara bagi perempuan dan laki-laki untuk mendapatkan pelayanan, informasi dan pendidikan terkait kesehatan seksual dan reproduksi.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('05', 'Kesetaraan Gender', '5.a', 'Melakukan reformasi untuk memberi hak yang sama kepada perempuan terhadap sumber daya ekonomi, serta akses terhadap kepemilikan dan kontrol atas tanah dan bentuk kepemilikan lain, jasa keuangan, warisan dan sumber daya alam, sesuai dengan hukum nasional.', '5.a.1*', '(1) Proporsi penduduk pertanian yang memiliki hak atas tanah pertanian; (2) Proporsi perempuan penduduk pertanian sebagai pemilik atau yang memiliki hak atas tanah pertanian, menurut jenis kepemilikan.', 'Nasional/Global', 'APPLICABLE', 'Apakah project mendukung perempuan petani untuk memiliki akses dan hak atas tanah serta sumber daya produktif yang setara dengan laki-laki?', 'Menilai kontribusi project dalam memperkuat hak atas tanah dan sumber daya bagi perempuan.'),
    ('05', 'Kesetaraan Gender', '5.a', 'Melakukan reformasi untuk memberi hak yang sama kepada perempuan terhadap sumber daya ekonomi, serta akses terhadap kepemilikan dan kontrol atas tanah dan bentuk kepemilikan lain, jasa keuangan, warisan dan sumber daya alam, sesuai dengan hukum nasional.', '5.a.2*', 'Ketersediaan kerangka hukum (termasuk hukum adat) yang menjamin persamaan hak perempuan untuk kepemilikan tanah dan/atau hak kontrol.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('05', 'Kesetaraan Gender', '5.b', 'Meningkatkan penggunaan teknologi yang memampukan, khususnya teknologi informasi dan komunikasi untuk meningkatkan pemberdayaan perempuan.', '5.b.1*', 'Proporsi individu yang menguasai/memiliki telepon genggam.', 'Nasional/Global', 'APPLICABLE', 'Apakah project meningkatkan akses dan penggunaan teknologi (termasuk telepon genggam dan alat digital) bagi perempuan petani atau penerima manfaat untuk mendukung pemberdayaan mereka?', 'Menilai kontribusi project terhadap pemberdayaan perempuan melalui akses teknologi.'),
    ('05', 'Kesetaraan Gender', '5.c', 'Mengadopsi dan memperkuat kebijakan yang baik dan perundang-undangan yang berlaku untuk peningkatan kesetaraan gender dan pemberdayaan kaum perempuan di semua tingkatan.', '5.c.1*', 'Ketersediaan sistem untuk melacak dan membuat alokasi umum untuk kesetaraan gender dan pemberdayaan perempuan.', 'Nasional/Global', 'APPLICABLE', 'Apakah project memiliki mekanisme untuk memantau dan mengalokasikan sumber daya bagi kesetaraan gender dan pemberdayaan perempuan dalam kegiatannya?', 'Menilai keberadaan mekanisme gender dalam pengelolaan project.'),
    ('06', 'Air Bersih dan Sanitasi Layak', '6.1', 'Pada tahun 2030, mencapai akses universal dan merata terhadap air minum yang aman dan terjangkau bagi semua.', '6.1.1*', 'Persentase rumah tangga yang menggunakan layanan air minum yang dikelola secara aman', 'Nasional/Global', 'APPLICABLE', 'Apakah project menyediakan atau memfasilitasi akses air bersih yang aman bagi pekerja, petani, dan penerima manfaat yang terlibat?', 'Menilai kontribusi project terhadap ketersediaan air bersih bagi pihak yang terlibat.'),
    ('06', 'Air Bersih dan Sanitasi Layak', '6.2', 'Pada tahun 2030, mencapai akses terhadap sanitasi dan kebersihan yang memadai dan merata bagi semua, dan menghentikan praktik buang air besar di tempat terbuka, memberikan perhatian khusus pada kebutuhan kaum perempuan, serta kelompok masyarakat rentan.', '6.2.1*', 'Persentase rumah tangga yang menggunakan layanan sanitasi yang dikelola secara aman dan fasilitas cuci tangan dengan air dan sabun', 'Nasional/Global', 'APPLICABLE', 'Apakah project menyediakan fasilitas sanitasi dan kebersihan (termasuk fasilitas cuci tangan) yang memadai bagi pekerja atau penerima manfaat yang terlibat?', 'Menilai penyediaan sanitasi dan fasilitas kebersihan dalam project.'),
    ('06', 'Air Bersih dan Sanitasi Layak', '6.3', 'Pada tahun 2030, meningkatkan kualitas air dengan mengurangi polusi, menghilangkan pembuangan, dan meminimalkan pelepasan material dan bahan kimia berbahaya, mengurangi setengah proporsi air limbah yang tidak diolah, dan secara signifikan meningkatkan daur ulang, serta penggunaan kembali barang daur ulang yang aman secara global.', '6.3.1.(a)', 'Persentase limbah cair industri cair yang diolah secara aman', 'Proxy', 'APPLICABLE', 'Apakah project mengolah limbah cair dari kegiatan pengolahan hasil pertanian secara aman sebelum dilepas ke lingkungan?', 'Menilai pengelolaan limbah cair kegiatan project.'),
    ('06', 'Air Bersih dan Sanitasi Layak', '6.3', 'Pada tahun 2030, meningkatkan kualitas air dengan mengurangi polusi, menghilangkan pembuangan, dan meminimalkan pelepasan material dan bahan kimia berbahaya, mengurangi setengah proporsi air limbah yang tidak diolah, dan secara signifikan meningkatkan daur ulang, serta penggunaan kembali barang daur ulang yang aman secara global.', '6.3.2.(a)', 'Indeks Kualitas Air (IKA)', 'Proxy', 'APPLICABLE', 'Apakah project menerapkan praktik yang menjaga atau meningkatkan kualitas air pada lahan dan sekitar kegiatan operasionalnya?', 'Menilai upaya project menjaga kualitas air.'),
    ('06', 'Air Bersih dan Sanitasi Layak', '6.4', 'Pada tahun 2030, secara signifikan meningkatkan efisiensi penggunaan air di semua sektor, dan menjamin penggunaan dan pasokan air tawar yang berkelanjutan untuk mengatasi kelangkaan air, dan secara signifikan mengurangi jumlah orang yang menderita akibat kelangkaan air.', '6.4.2.(a)', 'Proporsi pengambilan air baku bersumber dari air permukaan terhadap ketersediaannya', 'Proxy', 'APPLICABLE', 'Apakah project menerapkan penggunaan air yang efisien, misalnya melalui irigasi hemat air atau pengelolaan kebutuhan air yang efisien?', 'Menilai efisiensi penggunaan air dalam kegiatan project.'),
    ('06', 'Air Bersih dan Sanitasi Layak', '6.5', 'Pada tahun 2030, menerapkan pengelolaan sumber daya air terpadu di semua tingkatan, termasuk melalui kerjasama lintas batas yang tepat.', '6.5.1*', 'Tingkat pelaksanaan pengelolaan sumber daya air secara terpadu (0-100)', 'Nasional/Global', 'APPLICABLE', 'Apakah project menerapkan pengelolaan air secara terpadu yang mempertimbangkan aspek keberlanjutan dan keterlibatan para pihak dalam pengelolaan sumber daya air?', 'Menilai penerapan pengelolaan air terpadu dalam project.'),
    ('06', 'Air Bersih dan Sanitasi Layak', '6.5', 'Pada tahun 2030, menerapkan pengelolaan sumber daya air terpadu di semua tingkatan, termasuk melalui kerjasama lintas batas yang tepat.', '6.5.2*', 'Proporsi wilayah cekungan lintas batas dengan pengaturan kerja sama sumberdaya air yang operasional', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('06', 'Air Bersih dan Sanitasi Layak', '6.6', 'Pada tahun 2020, melindungi dan merestorasi ekosistem terkait sumber daya air, termasuk pegunungan, hutan, lahan basah, sungai, air tanah, dan danau.', '6.6.1.(a)', 'Indeks Kualitas Lahan', 'Proxy', 'APPLICABLE', 'Apakah project menjalankan kegiatan untuk melindungi atau merestorasi ekosistem yang terkait dengan sumber daya air (misalnya daerah tangkapan air, sungai, lahan basah) di sekitar area project?', 'Menilai kontribusi project terhadap perlindungan dan restorasi ekosistem terkait air.'),
    ('07', 'Energi Bersih dan Terjangkau', '7.1', 'Pada tahun 2030, menjamin akses universal layanan energi yang terjangkau, andal dan modern.', '7.1.1*', 'Rasio elektrifikasi', 'Nasional/Global', 'APPLICABLE', 'Apakah project menyediakan atau memfasilitasi akses energi yang andal dan terjangkau bagi kegiatan operasional dan atau penerima manfaat yang terlibat?', 'Menilai kontribusi project terhadap akses energi bagi operasional dan peserta.'),
    ('07', 'Energi Bersih dan Terjangkau', '7.1', 'Pada tahun 2030, menjamin akses universal layanan energi yang terjangkau, andal dan modern.', '7.1.1.[a]', 'Konsumsi listrik per kapita', 'Pengayaan', 'NOT_APPLICABLE', '', ''),
    ('07', 'Energi Bersih dan Terjangkau', '7.1', 'Pada tahun 2030, menjamin akses universal layanan energi yang terjangkau, andal dan modern.', '7.1.2.(a)', 'Jumlah sambungan jaringan gas untuk rumah tangga', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('07', 'Energi Bersih dan Terjangkau', '7.1', 'Pada tahun 2030, menjamin akses universal layanan energi yang terjangkau, andal dan modern.', '7.1.2.(b)', 'Proporsi rumah tangga yang menggunakan gas/LPG sebagai bahan bakar utama untuk memasak terhadap total rumah tangga', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('07', 'Energi Bersih dan Terjangkau', '7.1', 'Pada tahun 2030, menjamin akses universal layanan energi yang terjangkau, andal dan modern.', '7.1.2.(c)', 'Proporsi rumah tangga yang menggunakan listrik sebagai bahan bakar utama untuk memasak terhadap total rumah tangga', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('07', 'Energi Bersih dan Terjangkau', '7.2', 'Pada tahun 2030, meningkat secara substansial pangsa energi terbarukan dalam bauran energi global.', '7.2.1.(a)', 'Bauran energi terbarukan (dari energi primer)', 'Proxy', 'APPLICABLE', 'Apakah project menggunakan atau mengembangkan sumber energi terbarukan (misalnya tenaga surya, biomassa, biogas) dalam kegiatan operasionalnya?', 'Menilai kontribusi project terhadap penggunaan energi terbarukan.'),
    ('07', 'Energi Bersih dan Terjangkau', '7.3', 'Pada tahun 2030, melakukan perbaikan efisiensi energi di tingkat global sebanyak dua kali lipat.', '7.3.1*', 'Intensitas energi primer', 'Nasional/Global', 'APPLICABLE', 'Apakah project menerapkan langkah efisiensi energi (misalnya penggunaan peralatan hemat energi) untuk mengurangi konsumsi energi pada kegiatan operasional?', 'Menilai upaya efisiensi energi dalam project.'),
    ('07', 'Energi Bersih dan Terjangkau', '7.b', 'Pada tahun 2030, memperluas infrastruktur dan meningkatkan teknologi untuk penyediaan layanan energi modern dan berkelanjutan bagi semua negara-negara berkembang, khususnya negara kurang berkembang, negara berkembang pulau kecil dan negara berkembang.', '7.b.1*', 'Kapasitas Terpasang Pembangkit Listrik dari Energi Terbarukan (dalam watt per kapita)', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('08', 'Pekerjaan Layak dan Pertumbuhan Ekonomi', '8.1', 'Mempertahankan pertumbuhan ekonomi per kapita sesuai dengan kondisi nasional dan, khususnya, setidaknya 7 persen pertumbuhan produk domestik bruto per tahun di negara kurang berkembang.', '8.1.1*', 'Laju pertumbuhan PDB per kapita.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('08', 'Pekerjaan Layak dan Pertumbuhan Ekonomi', '8.1', 'Mempertahankan pertumbuhan ekonomi per kapita sesuai dengan kondisi nasional dan, khususnya, setidaknya 7 persen pertumbuhan produk domestik bruto per tahun di negara kurang berkembang.', '8.1.1.[a]', 'PDB per kapita', 'Pengayaan', 'NOT_APPLICABLE', '', ''),
    ('08', 'Pekerjaan Layak dan Pertumbuhan Ekonomi', '8.2', 'Mencapai tingkat produktivitas ekonomi yang lebih tinggi, melalui diversifikasi, peningkatan dan inovasi teknologi, termasuk melalui fokus pada sektor yang memberi nilai tambah tinggi dan padat karya.', '8.2.1*', 'Laju pertumbuhan PDB per tenaga kerja/Tingkat pertumbuhan PDB riil per orang bekerja per tahun.', 'Nasional/Global', 'APPLICABLE', 'Apakah project berupaya meningkatkan produktivitas tenaga kerja, misalnya melalui teknologi, inovasi, atau diversifikasi kegiatan produksi?', 'Menilai kontribusi project terhadap peningkatan produktivitas tenaga kerja.'),
    ('08', 'Pekerjaan Layak dan Pertumbuhan Ekonomi', '8.3', 'Menggalakkan kebijakan pembangunan yang mendukung kegiatan produktif, penciptaan lapangan kerja layak, kewirausahaan, kreativitas dan inovasi, dan mendorong formalisasi dan pertumbuhan usaha mikro, kecil, dan menengah, termasuk melalui akses terhadap jasa keuangan.', '8.3.1*', 'Proporsi lapangan kerja informal, berdasarkan sektor dan jenis kelamin.', 'Nasional/Global', 'APPLICABLE', 'Apakah project menciptakan lapangan kerja dan mendorong formalisasi serta kegiatan produktif bagi petani dan tenaga kerja yang terlibat?', 'Menilai kontribusi project terhadap penciptaan lapangan kerja dan formalisasi kegiatan produktif.'),
    ('08', 'Pekerjaan Layak dan Pertumbuhan Ekonomi', '8.3', 'Menggalakkan kebijakan pembangunan yang mendukung kegiatan produktif, penciptaan lapangan kerja layak, kewirausahaan, kreativitas dan inovasi, dan mendorong formalisasi dan pertumbuhan usaha mikro, kecil, dan menengah, termasuk melalui akses terhadap jasa keuangan.', '8.3.1.[a]', 'Proporsi UMKM yang mengakses kredit lembaga keuangan formal.', 'Pengayaan', 'APPLICABLE', 'Apakah project memfasilitasi petani atau pelaku usaha kecil yang terlibat untuk mengakses pembiayaan atau kredit dari lembaga keuangan formal?', 'Menilai kontribusi project terhadap akses pembiayaan bagi usaha kecil peserta.'),
    ('08', 'Pekerjaan Layak dan Pertumbuhan Ekonomi', '8.4', 'Meningkatkan secara progresif, hingga 2030, efisiensi sumber daya global dalam konsumsi dan produksi, serta usaha melepas kaitan pertumbuhan ekonomi dari degradasi lingkungan, sesuai dengan the 10-Year Framework of Programs on Sustainable Consumption and Production, dengan negara-negara maju sebagai pengarah.', '8.4.1.(a)', 'Rencana dan implementasi Strategi Pelaksanaan Sasaran Pola Konsumsi dan Produksi Berkelanjutan', 'Proxy', 'APPLICABLE', 'Apakah project menerapkan praktik produksi dan konsumsi yang berkelanjutan, termasuk penggunaan sumber daya secara efisien serta pengurangan dampak lingkungan dari produksi?', 'Menilai penerapan pola konsumsi dan produksi berkelanjutan dalam project.'),
    ('08', 'Pekerjaan Layak dan Pertumbuhan Ekonomi', '8.5', 'Pada tahun 2030, mencapai pekerjaan tetap dan produktif dan pekerjaan yang layak bagi semua perempuan dan laki-laki, termasuk bagi pemuda dan penyandang difabilitas, dan upah yang sama untuk pekerjaan yang sama nilainya.', '8.5.1*', 'Upah rata-rata per jam kerja.', 'Nasional/Global', 'APPLICABLE', 'Apakah project memberikan upah yang layak dan setara (tanpa diskriminasi) bagi pekerja yang terlibat untuk pekerjaan yang setara nilainya?', 'Menilai pemberian upah layak dan setara dalam project.'),
    ('08', 'Pekerjaan Layak dan Pertumbuhan Ekonomi', '8.5', 'Pada tahun 2030, mencapai pekerjaan tetap dan produktif dan pekerjaan yang layak bagi semua perempuan dan laki-laki, termasuk bagi pemuda dan penyandang difabilitas, dan upah yang sama untuk pekerjaan yang sama nilainya.', '8.5.2*', 'Tingkat pengangguran terbuka', 'Nasional/Global', 'APPLICABLE', 'Apakah project menciptakan kesempatan kerja yang produktif bagi penduduk setempat atau kelompok yang terlibat?', 'Menilai kontribusi project terhadap penyerapan tenaga kerja.'),
    ('08', 'Pekerjaan Layak dan Pertumbuhan Ekonomi', '8.5', 'Pada tahun 2030, mencapai pekerjaan tetap dan produktif dan pekerjaan yang layak bagi semua perempuan dan laki-laki, termasuk bagi pemuda dan penyandang difabilitas, dan upah yang sama untuk pekerjaan yang sama nilainya.', '8.5.2.[a]', 'Tingkat setengah pengangguran.', 'Pengayaan', 'APPLICABLE', 'Apakah project menyediakan kesempatan kerja yang cukup dan berkelanjutan sehingga tenaga kerja yang terlibat tidak hanya bekerja sebagian waktu yang tidak produktif?', 'Menilai ketersediaan kesempatan kerja yang memadai dalam project.'),
    ('08', 'Pekerjaan Layak dan Pertumbuhan Ekonomi', '8.6', 'Pada tahun 2020, secara substansial mengurangi proporsi usia muda yang tidak bekerja, tidak menempuh pendidikan atau pelatihan.', '8.6.1*', 'Persentase usia muda (15-24 tahun) yang sedang tidak sekolah, bekerja, atau mengikuti pelatihan (NEET)', 'Nasional/Global', 'APPLICABLE', 'Apakah project memberikan kesempatan kerja atau pelatihan keterampilan bagi pemuda yang terlibat sehingga mereka produktif?', 'Menilai kontribusi project terhadap kesempatan kerja/pelatihan pemuda.'),
    ('08', 'Pekerjaan Layak dan Pertumbuhan Ekonomi', '8.7', 'Mengambil tindakan cepat dan untuk memberantas kerja paksa, mengakhiri perbudakan dan penjualan manusia, mengamankan larangan dan penghapusan bentuk terburuk tenaga kerja anak, termasuk perekrutan dan penggunaan tentara anak-anak, dan pada tahun 2025 mengakhiri tenaga kerja anak dalam segala bentuknya.', '8.7.1*', 'Persentase dan jumlah anak usia 5-17 yang bekerja, dibedakan berdasarkan jenis kelamin dan pembagian kelompok umur berdasarkan International Conference of Labour Statisticians', 'Nasional/Global', 'APPLICABLE', 'Apakah project memiliki kebijakan dan mekanisme untuk mencegah penggunaan tenaga kerja anak dan kerja paksa dalam kegiatan operasionalnya?', 'Menilai pencegahan kerja anak dan kerja paksa dalam project.'),
    ('08', 'Pekerjaan Layak dan Pertumbuhan Ekonomi', '8.7', 'Mengambil tindakan cepat dan untuk memberantas kerja paksa, mengakhiri perbudakan dan penjualan manusia, mengamankan larangan dan penghapusan bentuk terburuk tenaga kerja anak, termasuk perekrutan dan penggunaan tentara anak-anak, dan pada tahun 2025 mengakhiri tenaga kerja anak dalam segala bentuknya.', '8.7.1.[a]', 'Persentase dan jumlah anak usia 5-17 yang bekerja, dibedakan berdasarkan jenis kelamin dan kelompok umur berdasarkan UU Ketenagakerjaan', 'Pengayaan', 'APPLICABLE', 'Apakah project memastikan kepatuhan terhadap ketentuan ketenagakerjaan untuk mencegah anak bekerja dalam kegiatan produksi?', 'Menilai kepatuhan project terhadap ketenagakerjaan anak.'),
    ('08', 'Pekerjaan Layak dan Pertumbuhan Ekonomi', '8.8', 'Melindungi hak-hak tenaga kerja dan mempromosikan lingkungan kerja yang aman dan terjamin bagi semua pekerja, termasuk pekerja migran, khususnya pekerja migran perempuan, dan mereka yang bekerja dalam pekerjaan berbahaya.', '8.8.1.(a)', 'Persentase cakupan kepesertaan Pekerja Bukan Penerima Upah (PBPU) jaminan sosial ketenagakerjaan nasional', 'Proxy', 'APPLICABLE', 'Apakah project memfasilitasi perlindungan jaminan sosial ketenagakerjaan bagi pekerja yang terlibat dalam project (termasuk pekerja bukan penerima upah/pekerja harian)?', 'Menilai perlindungan ketenagakerjaan bagi pekerja project.'),
    ('08', 'Pekerjaan Layak dan Pertumbuhan Ekonomi', '8.9', 'Pada tahun 2030, menyusun dan melaksanakan kebijakan untuk mempromosikan pariwisata berkelanjutan yang menciptakan lapangan kerja dan mempromosikan budaya dan produk lokal.', '8.9.1*', 'Proporsi dan laju pertumbuhan kontribusi pariwisata terhadap PDB', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('08', 'Pekerjaan Layak dan Pertumbuhan Ekonomi', '8.9', 'Pada tahun 2030, menyusun dan melaksanakan kebijakan untuk mempromosikan pariwisata berkelanjutan yang menciptakan lapangan kerja dan mempromosikan budaya dan produk lokal.', '8.9.1.[a]', 'Jumlah kunjungan wisatawan mancanegara.', 'Pengayaan', 'NOT_APPLICABLE', '', ''),
    ('08', 'Pekerjaan Layak dan Pertumbuhan Ekonomi', '8.9', 'Pada tahun 2030, menyusun dan melaksanakan kebijakan untuk mempromosikan pariwisata berkelanjutan yang menciptakan lapangan kerja dan mempromosikan budaya dan produk lokal.', '8.9.1.[b]', 'Jumlah perjalanan wisatawan nusantara.', 'Pengayaan', 'NOT_APPLICABLE', '', ''),
    ('08', 'Pekerjaan Layak dan Pertumbuhan Ekonomi', '8.9', 'Pada tahun 2030, menyusun dan melaksanakan kebijakan untuk mempromosikan pariwisata berkelanjutan yang menciptakan lapangan kerja dan mempromosikan budaya dan produk lokal.', '8.9.1.[c]', 'Jumlah devisa sektor pariwisata.', 'Pengayaan', 'NOT_APPLICABLE', '', ''),
    ('08', 'Pekerjaan Layak dan Pertumbuhan Ekonomi', '8.10', 'Memperkuat kapasitas lembaga keuangan domestik untuk mendorong dan memperluas akses terhadap perbankan, asuransi dan jasa keuangan bagi semua.', '8.10.1.(a)', 'Tingkat Inklusi Keuangan.', 'Proxy', 'APPLICABLE', 'Apakah project memfasilitasi petani, pekerja, atau penerima manfaat untuk memiliki akses terhadap layanan keuangan (rekening, pembayaran, kredit)?', 'Menilai kontribusi project terhadap akses keuangan peserta.'),
    ('08', 'Pekerjaan Layak dan Pertumbuhan Ekonomi', '8.10', 'Memperkuat kapasitas lembaga keuangan domestik untuk mendorong dan memperluas akses terhadap perbankan, asuransi dan jasa keuangan bagi semua.', '8.10.1.(b)', 'Rasio kredit UMKM terhadap total kredit perbankan.', 'Proxy', 'APPLICABLE', 'Apakah project membantu pelaku usaha kecil/mikro yang terlibat untuk mendapatkan pembiayaan dari lembaga keuangan?', 'Menilai fasilitasi akses kredit bagi usaha kecil peserta.'),
    ('08', 'Pekerjaan Layak dan Pertumbuhan Ekonomi', '8.10', 'Memperkuat kapasitas lembaga keuangan domestik untuk mendorong dan memperluas akses terhadap perbankan, asuransi dan jasa keuangan bagi semua.', '8.10.2.(a)', 'Jumlah rekening DPK perbankan per 1.000 penduduk dewasa.', 'Proxy', 'APPLICABLE', 'Apakah project mendorong petani atau penerima manfaat untuk memiliki rekening bank dan memanfaatkan layanan perbankan?', 'Menilai kontribusi project terhadap kepemilikan dan penggunaan rekening bank peserta.'),
    ('08', 'Pekerjaan Layak dan Pertumbuhan Ekonomi', '8.10', 'Memperkuat kapasitas lembaga keuangan domestik untuk mendorong dan memperluas akses terhadap perbankan, asuransi dan jasa keuangan bagi semua.', '8.10.2.(b)', 'Jumlah rekening uang elektronik per 1.000 penduduk dewasa.', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('08', 'Pekerjaan Layak dan Pertumbuhan Ekonomi', '8.b', 'Pada tahun 2020, mengembangkan dan mengoperasionalkan strategi global untuk ketenagakerjaan pemuda dan menerapkan the Global Jobs Pact of the International Labour Organization.', '8.b.1*', 'Adanya strategi nasional terkait ketenagakerjaan pemuda yang sudah dikembangkan dan operasional sebagai strategi khusus atau sebagai bagian dari strategi ketenagakerjaan nasional.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('09', 'Industri, Inovasi dan Infrastruktur', '9.1', 'Mengembangkan infrastruktur yang berkualitas, andal, berkelanjutan dan tangguh, termasuk infrastruktur regional dan lintas batas, untuk mendukung pembangunan ekonomi dan kesejahteraan manusia, dengan fokus pada akses yang terjangkau dan merata bagi semua.', '9.1.1.(a)', 'Kondisi mantap jalan nasional.', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('09', 'Industri, Inovasi dan Infrastruktur', '9.1', 'Mengembangkan infrastruktur yang berkualitas, andal, berkelanjutan dan tangguh, termasuk infrastruktur regional dan lintas batas, untuk mendukung pembangunan ekonomi dan kesejahteraan manusia, dengan fokus pada akses yang terjangkau dan merata bagi semua.', '9.1.1.(b)', 'Panjang jalan tol.', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('09', 'Industri, Inovasi dan Infrastruktur', '9.1', 'Mengembangkan infrastruktur yang berkualitas, andal, berkelanjutan dan tangguh, termasuk infrastruktur regional dan lintas batas, untuk mendukung pembangunan ekonomi dan kesejahteraan manusia, dengan fokus pada akses yang terjangkau dan merata bagi semua.', '9.1.1.(c)', 'Panjang jalur kereta api', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('09', 'Industri, Inovasi dan Infrastruktur', '9.1', 'Mengembangkan infrastruktur yang berkualitas, andal, berkelanjutan dan tangguh, termasuk infrastruktur regional dan lintas batas, untuk mendukung pembangunan ekonomi dan kesejahteraan manusia, dengan fokus pada akses yang terjangkau dan merata bagi semua.', '9.1.2*', 'Jumlah penumpang dan barang berdasarkan moda transportasi.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('09', 'Industri, Inovasi dan Infrastruktur', '9.1', 'Mengembangkan infrastruktur yang berkualitas, andal, berkelanjutan dan tangguh, termasuk infrastruktur regional dan lintas batas, untuk mendukung pembangunan ekonomi dan kesejahteraan manusia, dengan fokus pada akses yang terjangkau dan merata bagi semua.', '9.1.2.[a]', 'Jumlah bandara.', 'Pengayaan', 'NOT_APPLICABLE', '', ''),
    ('09', 'Industri, Inovasi dan Infrastruktur', '9.1', 'Mengembangkan infrastruktur yang berkualitas, andal, berkelanjutan dan tangguh, termasuk infrastruktur regional dan lintas batas, untuk mendukung pembangunan ekonomi dan kesejahteraan manusia, dengan fokus pada akses yang terjangkau dan merata bagi semua.', '9.1.2.[b]', 'Jumlah pelabuhan penyeberangan.', 'Pengayaan', 'NOT_APPLICABLE', '', ''),
    ('09', 'Industri, Inovasi dan Infrastruktur', '9.2', 'Mempromosikan industrialisasi inklusif dan berkelanjutan, dan pada tahun 2030, secara signifikan meningkatkan proporsi industri dalam lapangan kerja dan produk domestik bruto, sejalan dengan kondisi nasional, dan meningkatkan dua kali lipat proporsinya di negara kurang berkembang.', '9.2.1*', 'Rasio PDB industri pengolahan dan nilai tambah industri pengolahan per kapita', 'Nasional/Global', 'APPLICABLE', 'Apakah project melakukan kegiatan pengolahan hasil pertanian yang memberikan nilai tambah daripada hanya menjual bahan mentah?', 'Menilai kontribusi project terhadap kegiatan pengolahan bernilai tambah.'),
    ('09', 'Industri, Inovasi dan Infrastruktur', '9.2', 'Mempromosikan industrialisasi inklusif dan berkelanjutan, dan pada tahun 2030, secara signifikan meningkatkan proporsi industri dalam lapangan kerja dan produk domestik bruto, sejalan dengan kondisi nasional, dan meningkatkan dua kali lipat proporsinya di negara kurang berkembang.', '9.2.1.(a)', 'Pertumbuhan PDB industri pengolahan.', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('09', 'Industri, Inovasi dan Infrastruktur', '9.2', 'Mempromosikan industrialisasi inklusif dan berkelanjutan, dan pada tahun 2030, secara signifikan meningkatkan proporsi industri dalam lapangan kerja dan produk domestik bruto, sejalan dengan kondisi nasional, dan meningkatkan dua kali lipat proporsinya di negara kurang berkembang.', '9.2.2*', 'Proporsi tenaga kerja pada sektor industri pengolahan.', 'Nasional/Global', 'APPLICABLE', 'Apakah project memberikan kesempatan kerja pada kegiatan pengolahan hasil pertanian bagi tenaga kerja yang terlibat?', 'Menilai kontribusi project terhadap penyerapan tenaga kerja di kegiatan pengolahan.'),
    ('09', 'Industri, Inovasi dan Infrastruktur', '9.3', 'Meningkatkan akses industri dan perusahaan skala kecil, khususnya di negara berkembang, terhadap jasa keuangan, termasuk kredit terjangkau, dan mengintegrasikan ke dalam rantai nilai dan pasar.', '9.3.1*', 'Proporsi nilai tambah industri kecil terhadap total nilai tambah sektor industri.', 'Nasional/Global', 'APPLICABLE', 'Apakah project mendukung usaha kecil/mikro yang terlibat untuk meningkatkan nilai tambah dan terhubung ke pasar?', 'Menilai kontribusi project terhadap penguatan usaha kecil dan akses pasar.'),
    ('09', 'Industri, Inovasi dan Infrastruktur', '9.3', 'Meningkatkan akses industri dan perusahaan skala kecil, khususnya di negara berkembang, terhadap jasa keuangan, termasuk kredit terjangkau, dan mengintegrasikan ke dalam rantai nilai dan pasar.', '9.3.1.[a]', 'Industri kecil dan menengah (IKM) yang melakukan kemitraan dengan industri besar, sedang, dan sektor ekonomi lainnya.', 'Pengayaan', 'APPLICABLE', 'Apakah project memfasilitasi kemitraan antara usaha kecil/mikro yang terlibat dengan mitra yang lebih besar untuk akses pasar dan rantai nilai?', 'Menilai kontribusi project terhadap kemitraan usaha dan rantai nilai.'),
    ('09', 'Industri, Inovasi dan Infrastruktur', '9.3', 'Meningkatkan akses industri dan perusahaan skala kecil, khususnya di negara berkembang, terhadap jasa keuangan, termasuk kredit terjangkau, dan mengintegrasikan ke dalam rantai nilai dan pasar.', '9.3.2*', 'Proporsi industri kecil dengan pinjaman atau kredit.', 'Nasional/Global', 'APPLICABLE', 'Apakah project membantu usaha kecil yang terlibat untuk memperoleh pinjaman atau kredit yang terjangkau?', 'Menilai kontribusi project terhadap akses kredit bagi usaha kecil.'),
    ('09', 'Industri, Inovasi dan Infrastruktur', '9.4', 'Pada tahun 2030, meningkatkan infrastruktur dan retrofit industri agar dapat berkelanjutan, dengan peningkatan efisiensi penggunaan sumberdaya dan adopsi yang lebih baik dari teknologi dan proses industri bersih dan ramah lingkungan, yang dilaksanakan semua negara sesuai kemampuan masing-masing.', '9.4.1*', 'Rasio emisi COâ‚‚/emisi gas rumah kaca dengan nilai tambah sektor industri manufaktur.', 'Nasional/Global', 'APPLICABLE', 'Apakah kegiatan pengolahan project menerapkan proses yang bersih dan efisien untuk mengurangi emisi terhadap nilai tambah yang dihasilkan?', 'Menilai penerapan proses bersih/efisien pada kegiatan pengolahan project.'),
    ('09', 'Industri, Inovasi dan Infrastruktur', '9.4', 'Pada tahun 2030, meningkatkan infrastruktur dan retrofit industri agar dapat berkelanjutan, dengan peningkatan efisiensi penggunaan sumberdaya dan adopsi yang lebih baik dari teknologi dan proses industri bersih dan ramah lingkungan, yang dilaksanakan semua negara sesuai kemampuan masing-masing.', '9.4.1.[a]', 'Penurunan emisi gas rumah kaca sektor industri.', 'Pengayaan', 'APPLICABLE', 'Apakah project mengambil langkah untuk mengurangi emisi gas rumah kaca dari kegiatan produksi atau pengolahannya?', 'Menilai upaya pengurangan emisi pada kegiatan project.'),
    ('09', 'Industri, Inovasi dan Infrastruktur', '9.4', 'Pada tahun 2030, meningkatkan infrastruktur dan retrofit industri agar dapat berkelanjutan, dengan peningkatan efisiensi penggunaan sumberdaya dan adopsi yang lebih baik dari teknologi dan proses industri bersih dan ramah lingkungan, yang dilaksanakan semua negara sesuai kemampuan masing-masing.', '9.4.1.[b]', 'Intensitas emisi sektor industri.', 'Pengayaan', 'APPLICABLE', 'Apakah project menerapkan teknologi dan proses produksi yang lebih ramah lingkungan untuk menekan intensitas emisi pada kegiatan pengolahan?', 'Menilai penerapan teknologi bersih untuk efisiensi emisi produksi.'),
    ('09', 'Industri, Inovasi dan Infrastruktur', '9.5', 'Memperkuat riset ilmiah, meningkatkan kapabilitas teknologi sektor industri di semua negara, terutama negara-negara berkembang, termasuk pada tahun 2030, mendorong inovasi dan secara substansial meningkatkan jumlah pekerja penelitian dan pengembangan per 1 juta orang dan meningkatkan pembelanjaan publik dan swasta untuk penelitian dan pengembangan.', '9.5.1*', 'Proporsi anggaran riset terhadap PDB.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('09', 'Industri, Inovasi dan Infrastruktur', '9.5', 'Memperkuat riset ilmiah, meningkatkan kapabilitas teknologi sektor industri di semua negara, terutama negara-negara berkembang, termasuk pada tahun 2030, mendorong inovasi dan secara substansial meningkatkan jumlah pekerja penelitian dan pengembangan per 1 juta orang dan meningkatkan pembelanjaan publik dan swasta untuk penelitian dan pengembangan.', '9.5.2*', 'Jumlah sumber daya manusia bidang ilmu pengetahuan dan teknologi (peneliti, perekayasa, dan dosen) pada instansi pemerintah dan perguruan tinggi per satu juta penduduk.', 'Nasional/Global', 'APPLICABLE', 'Apakah project mendorong adopsi teknologi dan inovasi pertanian, termasuk melalui keterlibatan tenaga ahli atau penelitian dalam kegiatannya?', 'Menilai kontribusi project terhadap inovasi dan adopsi teknologi.'),
    ('09', 'Industri, Inovasi dan Infrastruktur', '9.5', 'Memperkuat riset ilmiah, meningkatkan kapabilitas teknologi sektor industri di semua negara, terutama negara-negara berkembang, termasuk pada tahun 2030, mendorong inovasi dan secara substansial meningkatkan jumlah pekerja penelitian dan pengembangan per 1 juta orang dan meningkatkan pembelanjaan publik dan swasta untuk penelitian dan pengembangan.', '9.5.2.[a]', 'Proporsi sumberdaya manusia bidang ilmu pengetahuan dan teknologi dengan gelar Doktor (S3).', 'Pengayaan', 'NOT_APPLICABLE', '', ''),
    ('09', 'Industri, Inovasi dan Infrastruktur', '9.b', 'Mendukung pengembangan teknologi domestic, riset dan inovasi di negara-negara berkembang, termasuk dengan memastikan lingkungan kebijakan yang kondusif, antara lain untuk diversifikasi industry dan peningkatan nilai tambah komoditas.', '9.b.1.(a)', 'Kontribusi ekspor produk berteknologi menengah dan tinggi Indonesia terhadap total ekspor produk Indonesia', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('09', 'Industri, Inovasi dan Infrastruktur', '9.c', 'Secara signifikan meningkatkan akses terhadap teknologi informasi dan komunikasi, dan mengusahakan penyediaan akses universasl dan terjangkau Internet di negara-negara kurang berkembang pada tahun 2020.', '9.c.1*', 'Proporsi penduduk terlayani mobile broadband.', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('10', 'Berkurangnya Kesenjangan', '10.1', 'Pada tahun 2030, secara progresif mencapai dan mempertahankan pertumbuhan pendapatan penduduk yang berada di bawah 40% dari populasi pada tingkat yang lebih tinggi dari rata-rata nasional.', '10.1.1.(a)', 'Rasio Gini', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('10', 'Berkurangnya Kesenjangan', '10.1', 'Pada tahun 2030, secara progresif mencapai dan mempertahankan pertumbuhan pendapatan penduduk yang berada di bawah 40% dari populasi pada tingkat yang lebih tinggi dari rata-rata nasional.', '10.1.1.(b)', 'Persentase penduduk yang hidup di bawah garis kemiskinan nasional, menurut jenis kelamin dan kelompok umur', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('10', 'Berkurangnya Kesenjangan', '10.1', 'Pada tahun 2030, secara progresif mencapai dan mempertahankan pertumbuhan pendapatan penduduk yang berada di bawah 40% dari populasi pada tingkat yang lebih tinggi dari rata-rata nasional.', '10.1.1.(c)', 'Jumlah desa tertinggal', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('10', 'Berkurangnya Kesenjangan', '10.1', 'Pada tahun 2030, secara progresif mencapai dan mempertahankan pertumbuhan pendapatan penduduk yang berada di bawah 40% dari populasi pada tingkat yang lebih tinggi dari rata-rata nasional.', '10.1.1.(d)', 'Jumlah Desa Mandiri', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('10', 'Berkurangnya Kesenjangan', '10.1', 'Pada tahun 2030, secara progresif mencapai dan mempertahankan pertumbuhan pendapatan penduduk yang berada di bawah 40% dari populasi pada tingkat yang lebih tinggi dari rata-rata nasional.', '10.1.1.(e)', 'Jumlah daerah tertinggal.', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('10', 'Berkurangnya Kesenjangan', '10.1', 'Pada tahun 2030, secara progresif mencapai dan mempertahankan pertumbuhan pendapatan penduduk yang berada di bawah 40% dari populasi pada tingkat yang lebih tinggi dari rata-rata nasional.', '10.1.1.(f)', 'Persentase penduduk miskin di daerah tertinggal.', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('10', 'Berkurangnya Kesenjangan', '10.2', 'Pada tahun 2030, memberdayakan dan meningkatkan inklusi sosial, ekonomi dan politik bagi semua, terlepas dari usia, jenis kelamin, difabilitas, ras, suku, asal, agama atau kemampuan ekonomi atau status lainnya.', '10.2.1*', 'Proporsi penduduk yang hidup di bawah 50 persen dari median pendapatan, menurut jenis kelamin dan penyandang disabilitas', 'Nasional/Global', 'APPLICABLE', 'Apakah project memastikan keterlibatan dan pemberdayaan kelompok rentan (termasuk penyandang disabilitas, perempuan, dan kelompok berpendapatan rendah) dalam kegiatannya?', 'Menilai kontribusi project terhadap inklusi sosial dan ekonomi kelompok rentan.'),
    ('10', 'Berkurangnya Kesenjangan', '10.3', 'Menjamin kesempatan yang sama dan mengurangi kesenjangan hasil, termasuk dengan menghapus hukum, kebijakan dan praktik yang diskriminatif, dan mempromosikan legislasi, kebijakan dan tindakan yang tepat terkait legislasi dan kebijakan tersebut.', '10.3.1.(a)', 'Indeks Aspek Kebebasan', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('10', 'Berkurangnya Kesenjangan', '10.3', 'Menjamin kesempatan yang sama dan mengurangi kesenjangan hasil, termasuk dengan menghapus hukum, kebijakan dan praktik yang diskriminatif, dan mempromosikan legislasi, kebijakan dan tindakan yang tepat terkait legislasi dan kebijakan tersebut.', '10.3.1.(b)', 'Jumlah penanganan pengaduan pelanggaran Hak Asasi Manusia (HAM).', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('10', 'Berkurangnya Kesenjangan', '10.3', 'Menjamin kesempatan yang sama dan mengurangi kesenjangan hasil, termasuk dengan menghapus hukum, kebijakan dan praktik yang diskriminatif, dan mempromosikan legislasi, kebijakan dan tindakan yang tepat terkait legislasi dan kebijakan tersebut.', '10.3.1.(c)', 'Jumlah penanganan pengaduan pelanggaran Hak Asasi Manusia (HAM) perempuan terutama kekerasan terhadap perempuan', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('10', 'Berkurangnya Kesenjangan', '10.3', 'Menjamin kesempatan yang sama dan mengurangi kesenjangan hasil, termasuk dengan menghapus hukum, kebijakan dan praktik yang diskriminatif, dan mempromosikan legislasi, kebijakan dan tindakan yang tepat terkait legislasi dan kebijakan tersebut.', '10.3.1.(d)', 'Jumlah kebijakan yang diskriminatif dalam 12 bulan lalu berdasarkan pelarangan diskriminasi menurut hukum HAM internasional', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('10', 'Berkurangnya Kesenjangan', '10.4', 'Mengadopsi kebijakan, terutama kebijakan fiskal, upah dan perlindungan sosial, serta secara progresif mencapai kesetaraan yang lebih besar.', '10.4.1.(a)', 'Persentase rencana anggaran untuk belanja fungsi perlindungan sosial pemerintah pusat', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('10', 'Berkurangnya Kesenjangan', '10.4', 'Mengadopsi kebijakan, terutama kebijakan fiskal, upah dan perlindungan sosial, serta secara progresif mencapai kesetaraan yang lebih besar.', '10.4.1.(b)', 'Persentase cakupan kepesertaan Jaminan Sosial Ketenagakerjaan', 'Proxy', 'APPLICABLE', 'Apakah project memfasilitasi pekerja yang terlibat agar memiliki akses terhadap jaminan sosial ketenagakerjaan sehingga mengurangi kesenjangan perlindungan?', 'Menilai kontribusi project terhadap akses jaminan sosial ketenagakerjaan pekerja.'),
    ('10', 'Berkurangnya Kesenjangan', '10.5', 'Memperbaiki regulasi dan pengawasan pasar dan lembaga keuangan global, dan memperkuat pelaksanaan regulasinya.', '10.5.1.(a)', 'Indikator Kesehatan Perbankan', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('10', 'Berkurangnya Kesenjangan', '10.6', 'Memastikan peningkatan representasi dan suara bagi negara berkembang dalam pengambilan keputusan di lembaga-lembaga ekonomi dan keuangan internasional global, untuk membentuk kelembagaan yang lebih efektif, kredibel, akuntabel dan terlegitimasi.', '10.6.1.(a)', 'Jumlah keanggotaan dan kontribusi dalam forum dan organisasi internasional', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('10', 'Berkurangnya Kesenjangan', '10.7', 'Memfasilitasi migrasi dan mobilitas manusia yang teratur, aman, berkala dan bertanggung jawab, termasuk melalui penerapan kebijakan migrasi yang terencana dan terkelola dengan baik.', '10.7.2.(a)', 'Jumlah dokumen kerja sama ketenagakerjaan dan pelindungan pekerja migran antara negara RI dengan negara tujuan penempatan', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('10', 'Berkurangnya Kesenjangan', '10.7', 'Memfasilitasi migrasi dan mobilitas manusia yang teratur, aman, berkala dan bertanggung jawab, termasuk melalui penerapan kebijakan migrasi yang terencana dan terkelola dengan baik.', '10.7.2.(b)', 'Jumlah fasilitasi pelayanan penempatan pekerja migran Indonesia berdasarkan okupasi.', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('11', 'Kota dan Permukiman yang Berkelanjutan', '11.1', 'Pada tahun 2030, menjamin akses bagi semua terhadap perumahan yang layak, aman, terjangkau, dan pelayanan dasar, serta menata kawasan kumuh.', '11.1.1.(a)', 'Proporsi rumah tangga yang memiliki akses terhadap hunian yang layak dan terjangkau', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('11', 'Kota dan Permukiman yang Berkelanjutan', '11.2', 'Pada tahun 2030, menyediakan akses terhadap sistem transportasi yang aman, terjangkau, mudah diakses dan berkelanjutan untuk semua, meningkatkan keselamatan lalu lintas, terutama dengan memperluas jangkauan transportasi umum, dengan memberi perhatian khusus pada kebutuhan mereka yang berada dalam situasi rentan, perempuan, anak, penyandang difabilitas dan orang tua.', '11.2.1.(a)', 'Proporsi populasi yang mendapatkan akses yang nyaman pada transportasi publik', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('11', 'Kota dan Permukiman yang Berkelanjutan', '11.2', 'Pada tahun 2030, menyediakan akses terhadap sistem transportasi yang aman, terjangkau, mudah diakses dan berkelanjutan untuk semua, meningkatkan keselamatan lalu lintas, terutama dengan memperluas jangkauan transportasi umum, dengan memberi perhatian khusus pada kebutuhan mereka yang berada dalam situasi rentan, perempuan, anak, penyandang difabilitas dan orang tua.', '11.2.1.(b)', 'Persentase penduduk terlayani transportasi umum', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('11', 'Kota dan Permukiman yang Berkelanjutan', '11.3', 'Pada tahun 2030, memperkuat urbanisasi yang inklusif dan berkelanjutan serta kapasitas partisipasi, perencanaan penanganan permukiman yang berkelanjutan dan terintegrasi di semua negara.', '11.3.1.(a)', 'Rasio laju perluasan lahan terbangun terhadap laju pertumbuhan penduduk', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('11', 'Kota dan Permukiman yang Berkelanjutan', '11.5', 'Pada tahun 2030, secara signifikan mengurangi jumlah kematian dan jumlah orang terdampak, dan secara substansial mengurangi kerugian ekonomi relatif terhadap PDB global yang disebabkan oleh bencana, dengan fokus melindungi orang miskin dan orang-orang dalam situasi rentan.', '11.5.1*', 'Jumlah korban meninggal, hilang, dan terkena dampak bencana per 100.000 orang', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('11', 'Kota dan Permukiman yang Berkelanjutan', '11.5', 'Pada tahun 2030, secara signifikan mengurangi jumlah kematian dan jumlah orang terdampak, dan secara substansial mengurangi kerugian ekonomi relatif terhadap PDB global yang disebabkan oleh bencana, dengan fokus melindungi orang miskin dan orang-orang dalam situasi rentan.', '11.5.2.(a)', 'Proporsi kerugian ekonomi langsung akibat bencana relatif terhadap pendapatan domestik bruto', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('11', 'Kota dan Permukiman yang Berkelanjutan', '11.5', 'Pada tahun 2030, secara signifikan mengurangi jumlah kematian dan jumlah orang terdampak, dan secara substansial mengurangi kerugian ekonomi relatif terhadap PDB global yang disebabkan oleh bencana, dengan fokus melindungi orang miskin dan orang-orang dalam situasi rentan.', '11.5.3*', '(a) Kerusakan pada infrastruktur vital dan (b) jumlah gangguan pada layanan dasar, akibat bencana', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('11', 'Kota dan Permukiman yang Berkelanjutan', '11.6', 'Pada tahun 2030, mengurangi dampak lingkungan perkotaan per kapita yang merugikan, termasuk dengan memberi perhatian khusus pada kualitas udara, termasuk penanganan sampah kota.', '11.6.1.(a)', 'Persentase rumah tangga dengan layanan penuh pengumpulan sampah', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('11', 'Kota dan Permukiman yang Berkelanjutan', '11.6', 'Pada tahun 2030, mengurangi dampak lingkungan perkotaan per kapita yang merugikan, termasuk dengan memberi perhatian khusus pada kualitas udara, termasuk penanganan sampah kota.', '11.6.1.(b)', 'Persentase timbulan sampah terolah di fasilitas pengolahan sampah', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('11', 'Kota dan Permukiman yang Berkelanjutan', '11.6', 'Pada tahun 2030, mengurangi dampak lingkungan perkotaan per kapita yang merugikan, termasuk dengan memberi perhatian khusus pada kualitas udara, termasuk penanganan sampah kota.', '11.6.2.(a)', 'Rata-rata tahunan materi partikulat halus PM 10', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('11', 'Kota dan Permukiman yang Berkelanjutan', '11.6', 'Pada tahun 2030, mengurangi dampak lingkungan perkotaan per kapita yang merugikan, termasuk dengan memberi perhatian khusus pada kualitas udara, termasuk penanganan sampah kota.', '11.6.2.(b)', 'Indeks Kualitas Udara', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('11', 'Kota dan Permukiman yang Berkelanjutan', '11.7', 'Pada tahun 2030, menyediakan ruang publik dan ruang terbuka hijau yang aman, inklusif dan mudah dijangkau terutama untuk perempuan dan anak, manula dan penyandang difabilitas.', '11.7.2.(a)', 'Proporsi penduduk yang mengalami kejahatan kekerasan dalam 12 bulan terakhir', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('11', 'Kota dan Permukiman yang Berkelanjutan', '11.a', 'Mendukung hubungan ekonomi, sosial, dan lingkungan antara urban, pinggiran kota, dan perdesaan dengan memperkuat perencanaan pembangunan nasional dan daerah.', '11.a.1.(a)', 'Proporsi penduduk yang tinggal di daerah dengan perencanaan tata ruang dan perencanaan pembangunan yang sudah dilengkapi KLHS', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('11', 'Kota dan Permukiman yang Berkelanjutan', '11.b', 'Pada tahun 2020, meningkatkan secara substansial jumlah kota dan permukiman yang mengadopsi dan mengimplementasi kebijakan dan perencanaan yang terintegrasi tentang penyertaan, efisiensi sumber daya, mitigasi dan adaptasi terhadap perubahan iklim, ketahanan terhadap bencana, serta mengembangkan dan mengimplementasikan penanganan holistik risiko bencana di semua lini, sesuai dengan the Sendai Framework for Disaster Risk Reduction 2015-2030.', '11.b.1*', 'Rencana dan implementasi strategi nasional penanggulangan bencana yang selaras dengan the Sendai Framework for Disaster Risk Reduction 2015â€“2030', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('11', 'Kota dan Permukiman yang Berkelanjutan', '11.b', 'Pada tahun 2020, meningkatkan secara substansial jumlah kota dan permukiman yang mengadopsi dan mengimplementasi kebijakan dan perencanaan yang terintegrasi tentang penyertaan, efisiensi sumber daya, mitigasi dan adaptasi terhadap perubahan iklim, ketahanan terhadap bencana, serta mengembangkan dan mengimplementasikan penanganan holistik risiko bencana di semua lini, sesuai dengan the Sendai Framework for Disaster Risk Reduction 2015-2030.', '11.b.2*', 'Persentase pemerintah daerah yang mengadopsi dan menerapkan strategi penanggulangan bencana daerah yang selaras dengan rencana/strategi nasional penanggulangan bencana', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('12', 'Konsumsi dan Produksi yang Bertanggung Jawab', '12.1', 'Melaksanakan the 10-Year Framework of Programmes on Sustainable Consumption and Production Patterns, dengan semua negara mengambil tindakan, dipimpin negara maju, dengan mempertimbangkan pembangunan dan kapasitas negara berkembang.', '12.1.1*', 'Rencana dan implementasi Strategi Pelaksanaan Sasaran Pola Konsumsi dan Produksi Berkelanjutan', 'Nasional/Global', 'APPLICABLE', 'Apakah project menerapkan praktik konsumsi dan produksi berkelanjutan dalam kegiatan produksi, pengolahan, dan distribusinya?', 'Menilai penerapan pola konsumsi dan produksi berkelanjutan dalam project.'),
    ('12', 'Konsumsi dan Produksi yang Bertanggung Jawab', '12.3', 'Pada tahun 2030, mengurangi hingga setengahnya limbah pangan per kapita global di tingkat ritel dan konsumen dan mengurangi kehilangan makanan sepanjang rantai produksi dan pasokan termasuk kehilangan saat pasca panen.', '12.3.1.(a)', 'Persentase penurunan susut dan sisa pangan (food loss and waste)', 'Proxy', 'APPLICABLE', 'Apakah project menerapkan upaya untuk mengurangi susut hasil panen dan pemborosan pangan di sepanjang rantai produksi dan pasca panen?', 'Menilai kontribusi project terhadap pengurangan susut dan sisa pangan.'),
    ('12', 'Konsumsi dan Produksi yang Bertanggung Jawab', '12.4', 'Pada tahun 2020 mencapai pengelolaan bahan kimia dan semua jenis limbah yang ramah lingkungan, di sepanjang siklus hidupnya, sesuai kerangka kerja internasional yang disepakati dan secara signifikan mengurangi pencemaran bahan kimia dan limbah tersebut ke udara, air, dan tanah untuk meminimalkan dampak buruk terhadap kesehatan manusia dan lingkungan.', '12.4.1*', 'Peran aktif dalam mengikuti kesepakatan multilateral internasional tentang bahan kimia dan limbah berbahaya', 'Nasional/Global', 'APPLICABLE', 'Apakah project mengelola bahan kimia pertanian (misalnya pestisida, pupuk) dan limbah berbahaya secara ramah lingkungan dan sesuai ketentuan yang berlaku?', 'Menilai pengelolaan bahan kimia dan limbah berbahaya secara aman dalam project.'),
    ('12', 'Konsumsi dan Produksi yang Bertanggung Jawab', '12.4', 'Pada tahun 2020 mencapai pengelolaan bahan kimia dan semua jenis limbah yang ramah lingkungan, di sepanjang siklus hidupnya, sesuai kerangka kerja internasional yang disepakati dan secara signifikan mengurangi pencemaran bahan kimia dan limbah tersebut ke udara, air, dan tanah untuk meminimalkan dampak buruk terhadap kesehatan manusia dan lingkungan.', '12.4.1.[a]', 'Persentase pengurangan dan penghapusan merkuri dari baseline 50 ton penggunaan merkuri', 'Pengayaan', 'NOT_APPLICABLE', '', ''),
    ('12', 'Konsumsi dan Produksi yang Bertanggung Jawab', '12.4', 'Pada tahun 2020 mencapai pengelolaan bahan kimia dan semua jenis limbah yang ramah lingkungan, di sepanjang siklus hidupnya, sesuai kerangka kerja internasional yang disepakati dan secara signifikan mengurangi pencemaran bahan kimia dan limbah tersebut ke udara, air, dan tanah untuk meminimalkan dampak buruk terhadap kesehatan manusia dan lingkungan.', '12.4.1.[b]', 'Persentase penurunan tingkat konsumsi perusak ozon dari baseline', 'Pengayaan', 'NOT_APPLICABLE', '', ''),
    ('12', 'Konsumsi dan Produksi yang Bertanggung Jawab', '12.4', 'Pada tahun 2020 mencapai pengelolaan bahan kimia dan semua jenis limbah yang ramah lingkungan, di sepanjang siklus hidupnya, sesuai kerangka kerja internasional yang disepakati dan secara signifikan mengurangi pencemaran bahan kimia dan limbah tersebut ke udara, air, dan tanah untuk meminimalkan dampak buruk terhadap kesehatan manusia dan lingkungan.', '12.4.2*', '(a) Jumlah Limbah B3 per kapita; (b) Proporsi limbah B3 yang ditangani/diolah berdasarkan jenis penanganannya/pengelolaannya', 'Nasional/Global', 'APPLICABLE', 'Apakah project mengidentifikasi, mengelola, dan mengolah limbah B3 (misalnya sisa pestisida, kemasan sejenis) secara aman sesuai ketentuan?', 'Menilai pengelolaan limbah B3 dalam project.'),
    ('12', 'Konsumsi dan Produksi yang Bertanggung Jawab', '12.5', 'Pada tahun 2030, secara substansial mengurangi produksi limbah melalui pencegahan, pengurangan, daur ulang, dan penggunaan kembali.', '12.5.1.(a)', 'Persentase timbulan sampah yang didaur ulang di fasilitas pengolahan sampah', 'Proxy', 'APPLICABLE', 'Apakah project menerapkan pencegahan, pengurangan, atau daur ulang limbah dari kegiatan produksinya (misalnya pemanfaatan sisa pertanian)?', 'Menilai upaya pengurangan dan daur ulang limbah dalam project.'),
    ('12', 'Konsumsi dan Produksi yang Bertanggung Jawab', '12.6', 'Mendorong perusahaan, terutama perusahaan besar dan transnasional, untuk mengadopsi praktek-praktek berkelanjutan dan mengintegrasikan informasi keberlanjutan dalam siklus pelaporan mereka.', '12.6.1*', 'Jumlah perusahaan yang mempublikasi laporan keberlanjutan (Sustainability Report)', 'Nasional/Global', 'APPLICABLE', 'Apakah project mendokumentasikan dan melaporkan praktik keberlanjutan dari kegiatannya?', 'Menilai transparansi pelaporan keberlanjutan project.'),
    ('12', 'Konsumsi dan Produksi yang Bertanggung Jawab', '12.6', 'Mendorong perusahaan, terutama perusahaan besar dan transnasional, untuk mengadopsi praktek-praktek berkelanjutan dan mengintegrasikan informasi keberlanjutan dalam siklus pelaporan mereka.', '12.6.1.[a]', 'Jumlah perusahaan yang menerapkan sertifikasi SNI ISO 14001', 'Pengayaan', 'APPLICABLE', 'Apakah project menerapkan standar atau sertifikasi pengelolaan lingkungan (seperti sertifikasi keberlanjutan atau ISO 14001) pada kegiatannya?', 'Menilai penerapan standar pengelolaan lingkungan oleh project.'),
    ('12', 'Konsumsi dan Produksi yang Bertanggung Jawab', '12.7', 'Mempromosikan praktek pengadaan publik yang berkelanjutan, sesuai dengan kebijakan dan prioritas nasional.', '12.7.1.(a)', 'Jumlah produk ramah lingkungan yang teregister dan masuk dalam pengadaan barang dan jasa pemerintah', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('12', 'Konsumsi dan Produksi yang Bertanggung Jawab', '12.7', 'Mempromosikan praktek pengadaan publik yang berkelanjutan, sesuai dengan kebijakan dan prioritas nasional.', '12.7.1.(b)', 'Jumlah Dokumen Penerapan Label Ramah Lingkungan untuk pengadaan Barang dan Jasa', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('12', 'Konsumsi dan Produksi yang Bertanggung Jawab', '12.8', 'Pada tahun 2030, menjamin bahwa masyarakat di mana pun memiliki informasi yang relevan dan kesadaran terhadap pembangunan berkelanjutan dan gaya hidup yang selaras dengan alam.', '12.8.1*', 'Tingkat pengarustamaan pendidikan kewarganegaraan global dan pendidikan untuk pembangunan berkelanjutan ke dalam (a) kebijakan pendidikan nasional, (b) kurikulum, (c) pendidikan guru, dan (d) penilaian siswa', 'Nasional/Global', 'APPLICABLE', 'Apakah project meningkatkan kesadaran petani dan penerima manfaat tentang praktik berkelanjutan dan gaya hidup selaras alam (misalnya melalui edukasi dan penyuluhan)?', 'Menilai kontribusi project terhadap kesadaran dan edukasi keberlanjutan.'),
    ('12', 'Konsumsi dan Produksi yang Bertanggung Jawab', '12.8', 'Pada tahun 2030, menjamin bahwa masyarakat di mana pun memiliki informasi yang relevan dan kesadaran terhadap pembangunan berkelanjutan dan gaya hidup yang selaras dengan alam.', '12.8.1.[a]', 'Jumlah satuan Pendidikan formal dan Lembaga/komunitas masyarakat peduli dan berbudaya lingkungan hidup', 'Pengayaan', 'APPLICABLE', 'Apakah project menjalin kemitraan dengan komunitas atau lembaga yang peduli lingkungan untuk meningkatkan praktik berkelanjutan?', 'Menilai keterlibatan project dengan komunitas peduli lingkungan.'),
    ('12', 'Konsumsi dan Produksi yang Bertanggung Jawab', '12.a', 'Mendukungan negara-negara berkembang untuk memperkuat kapasitas ilmu pengetahuan dan teknologi mereka untuk bergerak ke arah pola konsumsi dan produksi yang lebih berkelanjutan.', '12.a.1*', 'Kapasitas pembangkit energi terbarukan yang terpasang', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('12', 'Konsumsi dan Produksi yang Bertanggung Jawab', '12.b', 'Mengembangkan dan menerapkan perangkat untuk memantau dampak pembangunan berkelanjutan terhadap pariwisata berkelanjutan yang menciptakan lapangan kerja dan mempromosikan budaya dan produk lokal.', '12.b.1.(a)', 'Jumlah lokasi yang menerapkan pariwisata berkelanjutan (sustainable tourism development)', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('12', 'Konsumsi dan Produksi yang Bertanggung Jawab', '12.c', 'Merasionalisasi subsidi bahan bakar fosil tidak efisien yang mendorong pemborosan konsumsi dengan menghilangkan distorsi pasar, sesuai dengan keadaan nasional, termasuk dengan restrukturisasi pajak dan penghapusan secara bertahap jika ada subsidi berbahaya, yang dicerminkan oleh dampak lingkungannya, dengan sepenuhnya memperhitungkan kebutuhan dan kondisi khusus negara-negara berkembang dan meminimalkan dampak negatif yang bisa terjadi pada pembangunannya dengan cara yang melindungi rakyat miskin dan masyarakat yang terkena dampak.', '12.c.1*', '(a) Persentase subsidi bahan bakar fosil dari PDB; (b) Proporsi Subsidi Bahan Bakar Fosil dari total pengeluaran nasional untuk bahan bakar fosil', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('13', 'Penanganan Perubahan Iklim', '13.1', 'Memperkuat kapasitas ketahanan dan adaptasi terhadap bahaya terkait iklim dan bencana alam di semua negara.', '13.1.1.(a)', 'Jumlah korban meninggal, hilang dan terkena dampak bencana hidrometeorologi per 100.000 orang', 'Proxy', 'APPLICABLE', 'Apakah project menerapkan langkah ketahanan dan adaptasi terhadap bahaya terkait iklim (misalnya kekeringan, banjir) untuk melindungi lahan, hasil panen, dan penerima manfaat?', 'Menilai upaya project meningkatkan ketahanan terhadap bahaya iklim.'),
    ('13', 'Penanganan Perubahan Iklim', '13.1', 'Memperkuat kapasitas ketahanan dan adaptasi terhadap bahaya terkait iklim dan bencana alam di semua negara.', '13.1.1.(b)', 'Persentase penurunan potensi kehilangan PDB sektor terdampak bahaya iklim', 'Proxy', 'APPLICABLE', 'Apakah project mengambil tindakan untuk mengurangi risiko kehilangan hasil/lahan akibat bahaya iklim pada kegiatannya?', 'Menilai upaya project mengurangi potensi kerugian akibat bahaya iklim.'),
    ('13', 'Penanganan Perubahan Iklim', '13.1', 'Memperkuat kapasitas ketahanan dan adaptasi terhadap bahaya terkait iklim dan bencana alam di semua negara.', '13.1.2*', 'Rencana dan implementasi strategi nasional penanggulangan bencana yang selaras dengan the Sendai Framework for Disaster Risk Reduction 2015â€“2030', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('13', 'Penanganan Perubahan Iklim', '13.1', 'Memperkuat kapasitas ketahanan dan adaptasi terhadap bahaya terkait iklim dan bencana alam di semua negara.', '13.1.3*', 'Persentase pemerintah daerah yang mengadopsi dan menerapkan strategi penanggulangan bencana daerah yang selaras dengan rencana/strategi nasional penanggulangan bencana', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('13', 'Penanganan Perubahan Iklim', '13.2', 'Mengintegrasikan tindakan antisipasi perubahan iklim ke dalam kebijakan, strategi dan perencanaan nasional.', '13.2.1*', 'Terwujudnya penyelenggaraan inventarisasi gas rumah kaca (GRK), serta monitoring, pelaporan dan verifikasi emisi GRK yang dilaporkan dalam dokumen Biennial Update Report (BUR) dan National Communications', 'Nasional/Global', 'APPLICABLE', 'Apakah project melakukan pengukuran, inventarisasi, dan pemantauan emisi gas rumah kaca dari kegiatannya?', 'Menilai kontribusi project dalam pemantauan emisi GRK.'),
    ('13', 'Penanganan Perubahan Iklim', '13.2', 'Mengintegrasikan tindakan antisipasi perubahan iklim ke dalam kebijakan, strategi dan perencanaan nasional.', '13.2.2*', 'Jumlah emisi gas rumah kaca (GRK) per tahun', 'Nasional/Global', 'APPLICABLE', 'Apakah project menerapkan praktik yang mengurangi emisi gas rumah kaca dari kegiatan produksi dan pengolahannya?', 'Menilai kontribusi project terhadap pengurangan emisi GRK.'),
    ('13', 'Penanganan Perubahan Iklim', '13.2', 'Mengintegrasikan tindakan antisipasi perubahan iklim ke dalam kebijakan, strategi dan perencanaan nasional.', '13.2.2.[a]', 'Potensi penurunan emisi gas rumah kaca (GRK)', 'Pengayaan', 'APPLICABLE', 'Apakah project menghitung atau memanfaatkan potensi penurunan emisi (misalnya melalui serapan karbon atau praktik rendah emisi) dari kegiatannya?', 'Menilai upaya project memanfaatkan potensi penurunan emisi/karbon.'),
    ('13', 'Penanganan Perubahan Iklim', '13.2', 'Mengintegrasikan tindakan antisipasi perubahan iklim ke dalam kebijakan, strategi dan perencanaan nasional.', '13.2.2.[b]', 'Persentase potensi penurunan intensitas emisi gas rumah kaca (GRK)', 'Pengayaan', 'APPLICABLE', 'Apakah project mengadopsi teknologi dan praktik yang menurunkan intensitas emisi per unit produksi?', 'Menilai upaya efisiensi emisi per unit produksi project.'),
    ('13', 'Penanganan Perubahan Iklim', '13.3', 'Meningkatkan pendidikan, penumbuhan kesadaran, serta kapasitas manusia dan kelembagaan terkait mitigasi, adaptasi, pengurangan dampak dan peringatan dini perubahan iklim.', '13.3.1*', 'Tingkat pengarusutamaan pendidikan warga negara global dan pendidikan untuk pembangunan berkelanjutan ke dalam (a) kebijakan pendidikan nasional, (b) kurikulum, (c) pendidikan guru dan (d) asesmen siswa', 'Nasional/Global', 'APPLICABLE', 'Apakah project memberikan edukasi dan peningkatan kapasitas petani tentang mitigasi, adaptasi, dan peringatan dini perubahan iklim?', 'Menilai kontribusi project dalam edukasi dan kapasitas perubahan iklim.'),
    ('13', 'Penanganan Perubahan Iklim', '13.3', 'Meningkatkan pendidikan, penumbuhan kesadaran, serta kapasitas manusia dan kelembagaan terkait mitigasi, adaptasi, pengurangan dampak dan peringatan dini perubahan iklim.', '13.3.1.[a]', 'Jumlah satuan Pendidikan formal dan Lembaga/komunitas masyarakat peduli dan berbudaya lingkungan hidup', 'Pengayaan', 'APPLICABLE', 'Apakah project bermitra dengan lembaga atau komunitas untuk meningkatkan kesadaran dan kapasitas adaptasi iklim penerima manfaat?', 'Menilai kemitraan project untuk kapasitas adaptasi iklim.'),
    ('13', 'Penanganan Perubahan Iklim', '13.a', 'Melaksanakan komitmen negara maju pada the United Nations Framework Convention on Climate Change untuk tujuan mobilisasi dana bersama sebesar 100 miliar dolar Amerika per tahun pada tahun 2020 dari semua sumber untuk mengatasi kebutuhan negara berkembang dalam konteks aksi mitigasi yang bermanfaat dan transparansi dalam pelaksanaannya dan mengoperasionalisasi secara penuh the Green Climate Fund melalui kapitalisasi dana tersebut sesegera mungkin.', '13.a.1.(a)', 'Jumlah dana publik (budget tagging) untuk pendanaan perubahan iklim', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('14', 'Ekosistem Lautan', '14.1', 'Pada tahun 2025, mencegah dan secara signifikan mengurangi semua jenis pencemaran laut, khususnya dari kegiatan berbasis lahan, termasuk sampah laut dan polusi nutrisi.', '14.1.1.(a)', 'Persentase penurunan sampah terbuang ke laut', 'Proxy', 'APPLICABLE', 'Apakah project mengelola limbah dan sampah dari kegiatannya agar tidak terbuang ke perairan/laut di sekitar area operasional?', 'Menilai kontribusi project dalam mencegah pencemaran laut dari kegiatan berbasis lahan.'),
    ('14', 'Ekosistem Lautan', '14.2', 'Pada tahun 2020, mengelola dan melindungi ekosistem laut dan pesisir secara berkelanjutan untuk menghindari dampak buruk yang signifikan, termasuk dengan memperkuat ketahanannya, dan melakukan restorasi untuk mewujudkan lautan yang sehat dan produktif.', '14.2.1*', 'Penerapan pendekatan berbasis ekosistem dalam pengelolaan areal lautan', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('14', 'Ekosistem Lautan', '14.2', 'Pada tahun 2020, mengelola dan melindungi ekosistem laut dan pesisir secara berkelanjutan untuk menghindari dampak buruk yang signifikan, termasuk dengan memperkuat ketahanannya, dan melakukan restorasi untuk mewujudkan lautan yang sehat dan produktif.', '14.2.1.(a)', 'Terkelolanya 11 Wilayah Pengelolaan Perikanan Negara Republik Indonesia (WPPNRI) secara berkelanjutan', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('14', 'Ekosistem Lautan', '14.4', 'Pada tahun 2020, secara efektif mengatur pemanenan dan menghentikan penangkapan ikan yang berlebihan, penangkapan ikan ilegal dan praktek penangkapan ikan yang merusak, serta melaksanakan rencana pengelolaan berbasis ilmu pengetahuan, untuk memulihkan persediaan ikan secara layak dalam waktu yang paling singkat yang memungkinkan, setidaknya ke tingkat yang dapat memproduksi hasil maksimum yang berkelanjutan sesuai karakteristik biologisnya.', '14.4.1*', 'Proporsi tangkapan jenis ikan yang berada dalam batasan biologis yang aman', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('14', 'Ekosistem Lautan', '14.5', 'Pada tahun 2020, melestarikan setidaknya 10 persen dari wilayah pesisir dan laut, konsisten dengan hukum nasional dan internasional dan berdasarkan informasi ilmiah terbaik yang tersedia.', '14.5.1*', 'Jumlah luas kawasan konservasi perairan laut', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('14', 'Ekosistem Lautan', '14.6', 'Pada tahun 2020, melarang bentuk-bentuk subsidi perikanan tertentu yang berkontribusi terhadap kelebihan kapasitas dan penangkapan ikan berlebihan, menghilangkan subsidi yang berkontribusi terhadap penangkapan ikan ilegal, yang tidak dilaporkan & tidak diatur dan menahan jenis subsidi baru, dengan mengakui bahwa perlakuan khusus dan berbeda yang tepat dan efektif untuk negara berkembang & negara kurang berkembang harus menjadi bagian integral dari negosiasi subsidi perikanan pada the World Trade Organization.', '14.6.1.(a)', 'Persentase kepatuhan pelaku usaha perikanan', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('14', 'Ekosistem Lautan', '14.7', 'Pada tahun 2030, meningkatkan manfaat ekonomi bagi negara berkembang kepulauan kecil dan negara kurang berkembang dari pemanfaatan berkelanjutan sumber daya laut, termasuk melalui pengelolaan perikanan, budidaya air dan pariwisata yang berkelanjutan.', '14.7.1*', 'Persentase kontribusi perikanan berkelanjutan terhadap Produk Domestik Bruto (PDB)', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('14', 'Ekosistem Lautan', '14.b', 'Menyediakan akses untuk nelayan skala kecil (small-scale artisanal fishers) terhadap sumber daya laut dan pasar.', '14.b.1*', 'Ketersediaan kerangka hukum/regulasi/kebijakan/kelembagaan yang mengakui dan melindungi hak akses untuk perikanan skala kecil', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('14', 'Ekosistem Lautan', '14.b', 'Menyediakan akses untuk nelayan skala kecil (small-scale artisanal fishers) terhadap sumber daya laut dan pasar.', '14.b.1.[a]', 'Jumlah nelayan yang terlindungi', 'Pengayaan', 'NOT_APPLICABLE', '', ''),
    ('14', 'Ekosistem Lautan', '14.c', 'Meningkatkan pelestarian dan pemanfaatan berkelanjutan lautan dan sumber dayanya dengan menerapkan hukum internasional yang tercermin dalam the United Nations Convention on the Law of the Sea, yang menyediakan kerangka hukum untuk pelestarian dan pemanfaatan berkelanjutan lautan dan sumber dayanya, seperti yang tercantum dalam ayat 158 dari â€œThe future we wantâ€.', '14.c.1*', 'Tersedianya kerangka kebijakan dan instrumen terkait pelaksanaan UNCLOS (the United Nations Convention on the Law of the Sea)', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('15', 'Ekosistem Daratan', '15.1', 'Pada tahun 2020, menjamin pelestarian, restorasi dan pemanfaatan berkelanjutan dari ekosistem daratan dan perairan darat serta jasa lingkungannya, khususnya ekosistem hutan, lahan basah, pegunungan dan lahan kering, sejalan dengan kewajiban berdasarkan perjanjian internasional.', '15.1.1*', 'Proporsi tutupan hutan terhadap luas daratan', 'Nasional/Global', 'APPLICABLE', 'Apakah project berkontribusi pada pelestarian dan pemanfaatan berkelanjutan ekosistem daratan, termasuk mempertahankan atau merestorasi tutupan vegetasi di area project?', 'Menilai kontribusi project terhadap pelestarian ekosistem daratan/hutan.'),
    ('15', 'Ekosistem Daratan', '15.1', 'Pada tahun 2020, menjamin pelestarian, restorasi dan pemanfaatan berkelanjutan dari ekosistem daratan dan perairan darat serta jasa lingkungannya, khususnya ekosistem hutan, lahan basah, pegunungan dan lahan kering, sejalan dengan kewajiban berdasarkan perjanjian internasional.', '15.1.2*', 'Proporsi situs penting keanekaragaman hayati daratan dan perairan darat dalam kawasan konservasi, berdasarkan jenis ekosistemnya', 'Nasional/Global', 'APPLICABLE', 'Apakah project melindungi situs keanekaragaman hayati di area yang dikelolanya dan mempertimbangkan konservasi dalam pemanfaatan lahan?', 'Menilai perlindungan keanekaragaman hayati di area project.'),
    ('15', 'Ekosistem Daratan', '15.2', 'Pada tahun 2020, meningkatkan pelaksanaan pengelolaan semua jenis hutan secara berkelanjutan, menghentikan deforestasi, merestorasi hutan yang terdegradasi dan meningkatkan secara signifikan forestasi dan reforestasi secara global.', '15.2.1*', 'Kemajuan pengelolaan hutan lestari', 'Nasional/Global', 'APPLICABLE', 'Apakah project menerapkan pengelolaan yang menghindari deforestasi dan mendorong reforestasi atau restorasi vegetasi pada area yang dikelolanya?', 'Menilai kontribusi project terhadap pengelolaan hutan/lahan lestari dan pencegahan deforestasi.'),
    ('15', 'Ekosistem Daratan', '15.2', 'Pada tahun 2020, meningkatkan pelaksanaan pengelolaan semua jenis hutan secara berkelanjutan, menghentikan deforestasi, merestorasi hutan yang terdegradasi dan meningkatkan secara signifikan forestasi dan reforestasi secara global.', '15.2.1.(a)', 'Kemajuan menuju pengelolaan hutan lestari', 'Proxy', 'APPLICABLE', 'Apakah project menerapkan dan memantau praktik pengelolaan lahan lestari untuk menjaga fungsi ekosistem?', 'Menilai penerapan pengelolaan lahan lestari dan pemantauannya.'),
    ('15', 'Ekosistem Daratan', '15.3', 'Pada tahun 2020, menghentikan penggurunan, memulihkan lahan dan tanah kritis, termasuk lahan yang terkena penggurunan, kekeringan dan banjir, dan berusaha mencapai dunia yang bebas dari lahan terdegradasi.', '15.3.1*', 'Proporsi lahan yang terdegradasi terhadap luas daratan keseluruhan', 'Nasional/Global', 'APPLICABLE', 'Apakah project menerapkan praktik restorasi dan pencegahan degradasi lahan (misalnya konservasi tanah, penanaman penutup lahan) pada area yang dikelolanya?', 'Menilai kontribusi project terhadap restorasi dan pencegahan lahan terdegradasi.'),
    ('15', 'Ekosistem Daratan', '15.4', 'Pada tahun 2030, menjamin pelestarian ekosistem pegunungan, termasuk keanekaragaman hayatinya, untuk meningkatkan kapasitasnya memberikan manfaat yang sangat penting bagi pembangunan berkelanjutan.', '15.4.1*', 'Luas kawasan situs penting keanekaragaman hayati pegunungan dalam kawasan konservasi', 'Nasional/Global', 'APPLICABLE', 'Apakah project (khususnya di area pegunungan) melestarikan ekosistem dan keanekaragaman hayati serta menghindari kerusakan habitat?', 'Menilai pelestarian ekosistem pegunungan di area project.'),
    ('15', 'Ekosistem Daratan', '15.4', 'Pada tahun 2030, menjamin pelestarian ekosistem pegunungan, termasuk keanekaragaman hayatinya, untuk meningkatkan kapasitasnya memberikan manfaat yang sangat penting bagi pembangunan berkelanjutan.', '15.4.2*', 'Indeks tutupan hijau pegunungan', 'Nasional/Global', 'APPLICABLE', 'Apakah project menjaga tutupan hijau pada lahan (khususnya di area pegunungan) untuk mendukung fungsi ekosistem?', 'Menilai pemeliharaan tutupan vegetasi pada area project.'),
    ('15', 'Ekosistem Daratan', '15.5', 'Melakukan tindakan cepat dan signifikan untuk mengurangi degradasi habitat alami, menghentikan kehilangan keanekaragaman hayati, dan, pada tahun 2020, melindungi dan mencegah lenyapnya spesies yang terancam punah.', '15.5.1*', 'Indeks Daftar Merah Keanekaragaman hayati', 'Nasional/Global', 'APPLICABLE', 'Apakah project mengambil tindakan untuk mengurangi degradasi habitat alami dan mencegah kehilangan keanekaragaman hayati pada area yang dikelolanya?', 'Menilai kontribusi project terhadap konservasi keanekaragaman hayati.'),
    ('15', 'Ekosistem Daratan', '15.6', 'Meningkatkan pembagian keuntungan yang adil dan merata dari pemanfaatan sumber daya genetik, dan meningkatkan akses yang tepat terhadap sumber daya tersebut, sesuai kesepakatan internasional.', '15.6.1*', 'Kerangka kerja legislasi, administratif dan kebijakan untuk memastikan pembagian manfaat yang adil dan merata sumber daya genetik', 'Nasional/Global', 'APPLICABLE', 'Apakah project memastikan adanya pembagian manfaat yang adil saat memanfaatkan sumber daya genetik tanaman/ternak dan pengetahuan tradisional terkait?', 'Menilai pembagian manfaat sumber daya genetik dalam project.'),
    ('15', 'Ekosistem Daratan', '15.7', 'Melakukan tindakan cepat untuk mengakhiri perburuan dan perdagangan jenis flora dan fauna yang dilindungi serta mengatasi permintaan dan pasokan produk hidupan liar secara ilegal.', '15.7.1.(a)', 'Jumlah kasus perburuan atau perdagangan illegal tumbuhan dan satwa liar (TSL)', 'Proxy', 'APPLICABLE', 'Apakah project menerapkan kebijakan dan praktik yang mencegah perburuan atau perdagangan ilegal tumbuhan dan satwa liar di area operasionalnya?', 'Menilai pencegahan perburuan/perdagangan ilegal oleh project.'),
    ('15', 'Ekosistem Daratan', '15.8', 'Pada tahun 2020, memperkenalkan langkah-langkah untuk mencegah masuknya dan secara signifikan mengurangi dampak dari jenis asing invasif pada ekosistem darat dan air, serta mengendalikan atau memberantas jenis asing invasif prioritas.', '15.8.1*', 'Kerangka legislasi nasional yang relevan dan memadai dalam pencegahan atau pengendalian jenis asing invasive (JAI)', 'Nasional/Global', 'APPLICABLE', 'Apakah project menerapkan langkah pengendalian dan pencegahan masuknya jenis (spesies) asing invasif pada lahan yang dikelolanya?', 'Menilai kontribusi project dalam pencegahan/pengendalian spesies invasif.'),
    ('15', 'Ekosistem Daratan', '15.9', 'Pada tahun 2020, mengitegrasikan nilai-nilai ekosistem dan keanekaragaman hayati kedalam perencanaan nasional dan daerah, proses pembangunan, strategi dan penganggaran pengurangan kemiskinan.', '15.9.1.(a)', 'Rencana pemanfaatan Keanekaragaman Hayati Aichi 2 dari Rencana Strategis', 'Proxy', 'APPLICABLE', 'Apakah project mengintegrasikan nilai ekosistem dan keanekaragaman hayati ke dalam perencanaan kegiatan dan pengelolaan lahannya?', 'Menilai integrasi nilai biodiversitas dalam perencanaan project.'),
    ('15', 'Ekosistem Daratan', '15.a', 'Memobilisasi dan meningkatkan sumber daya keuangan secara signifikan dari semua sumber untuk melestarikan dan memanfaatkan keanekaragaman hayati dan ekosistem secara berkelanjutan.', '15.a.1.(a)', 'Jumlah dana hibah teregistrasi untuk pembangunan sektor kehutanan dan konservasi sumber daya air', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('15', 'Ekosistem Daratan', '15.b', 'Memobilisasi sumber daya penting dari semua sumber dan pada semua tingkatan untuk membiayai pengelolaan hutan yang berkelanjutan dan memberikan insentif yang memadai bagi negara berkembang untuk memajukan pengelolaannya, termasuk untuk pelestarian dan reforestasi.', '15.b.1.(a)', 'Jumlah dana hibah teregistrasi untuk pembangunan sektor kehutanan dan konservasi sumber daya air', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('15', 'Ekosistem Daratan', '15.c', 'Meningkatkan dukungan global dalam upaya memerangi perburuan dan perdagangan jenis yang dilindungi, termasuk dengan meningkatkan kapasitas masyarakat lokal mengejar peluang mata pencaharian yang berkelanjutan.', '15.c.1.(a)', 'Jumlah tumbuhan dan satwa liar dari hasil perburuan atau perdagangan ilegal', 'Proxy', 'APPLICABLE', 'Apakah project mendukung mata pencaharian masyarakat lokal secara berkelanjutan untuk mengurangi tekanan terhadap perburuan/perdagangan ilegal satwa dan tumbuhan dilindungi?', 'Menilai dukungan project terhadap pencegahan perburuan ilegal melalui mata pencaharian berkelanjutan.'),
    ('16', 'Perdamaian, Keadilan dan Kelembagaan yang Tangguh', '16.1', 'Secara signifikan mengurangi segala bentuk kekerasan dan terkait angka kematian dimanapun.', '16.1.1.(a)', 'Jumlah kasus kejahatan pembunuhan pada satu tahun terakhir', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('16', 'Perdamaian, Keadilan dan Kelembagaan yang Tangguh', '16.1', 'Secara signifikan mengurangi segala bentuk kekerasan dan terkait angka kematian dimanapun.', '16.1.2.(a)', 'Kematian disebabkan konflik per 100.000 penduduk', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('16', 'Perdamaian, Keadilan dan Kelembagaan yang Tangguh', '16.1', 'Secara signifikan mengurangi segala bentuk kekerasan dan terkait angka kematian dimanapun.', '16.1.3.(a)', 'Proporsi penduduk yang menjadi korban kejahatan kekerasan dalam 12 bulan terakhir', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('16', 'Perdamaian, Keadilan dan Kelembagaan yang Tangguh', '16.1', 'Secara signifikan mengurangi segala bentuk kekerasan dan terkait angka kematian dimanapun.', '16.1.4*', 'Proporsi penduduk yang merasa aman berjalan sendirian di area tempat tinggalnya', 'Nasional/Global', 'NOT_APPLICABLE', '', ''),
    ('16', 'Perdamaian, Keadilan dan Kelembagaan yang Tangguh', '16.2', 'Menghentikan perlakuan kejam, eksploitasi, perdagangan, dan segala bentuk kekerasan dan penyiksaan terhadap anak.', '16.2.1.(a)', 'Proporsi rumah tangga yang memiliki anak umur 1-17 tahun yang mengalami hukuman fisik dan/atau agresi psikologis dari pengasuh dalam setahun terakhir', 'Proxy', 'NOT_APPLICABLE', '', ''),
    ('16', 'Perdamaian, Keadilan dan Kelembagaan yang Tangguh', '16.2', 'Menghentikan perlakuan kejam, eksploitasi, perdagangan, dan segala bentuk kekerasan dan penyiksaan terhadap anak.', '16.2.1.(b)', 'Prevalensi anak usia 13-17 tahun yang pernah mengalami kekerasan sepanjang hidupnya', 'Proxy', 'NOT_APPLICABLE', '', ''),
